18	/// The longest tool-call id or name accepted, in bytes. Real ids and names are under 100 bytes. A
19	/// longer one is `Deviation("long_identifier")`: a completed block or call keeps its name for the
20	/// stream's life, so an unbounded one would be retained outside the held-byte accounting.
21	pub(crate) const MAX_IDENTIFIER_BYTES: usize = 1024;
