23	/// What a hold's calls are allowed to do once released.
24	#[derive(Debug, Clone, PartialEq, Eq)]
25	pub(crate) enum Verdict {
26	    /// Every call allowed: frames are released unchanged.
27	    AllowAll,
28	    /// One decision per call, in the hold's call order.
29	    PerCall(Vec<Decision>),
30	    /// Every call of the hold blocked, including calls not assembled yet.
31	    BlockAll(BlockCode),
32	    /// Observe mode: released unchanged and not enforced (§ 5.3).
33	    PassThrough,
34	}
35	
36	impl Verdict {
37	    pub(crate) fn blocks_any(&self) -> bool {
38	        match self {
39	            Verdict::AllowAll | Verdict::PassThrough => false,
40	            Verdict::BlockAll(_) => true,
41	            Verdict::PerCall(d) => d.iter().any(|d| !d.is_allow()),
42	        }
43	    }
44	
45	    /// The block code of the call in `slot` (its index within the hold), or `None` when allowed.
46	    pub(crate) fn block_code(&self, slot: usize) -> Option<BlockCode> {
47	        match self {
48	            Verdict::AllowAll | Verdict::PassThrough => None,
49	            Verdict::BlockAll(c) => Some(*c),
50	            Verdict::PerCall(d) => match d.get(slot) {
51	                Some(Decision::Block { code }) => Some(*code),
52	                Some(_) => None,
53	                None => Some(BlockCode::DeciderError), // D18: a missing decision is a block
54	            },
55	        }
56	    }
57	}
