61	/// One classified record, waiting in the queue or about to be released.
62	pub(crate) struct Frame {
63	    /// The validated Anthropic event name; `None` for OpenAI (P-1).
64	    pub event: Option<&'static str>,
65	    /// The original payload bytes, re-framed unchanged when nothing in it is blocked (D23).
66	    pub payload: Vec<u8>,
67	    /// The parsed payload; `None` only for OpenAI's `[DONE]`.
68	    pub value: Option<Value>,
