74	    Frame {
75	        frame: Frame,
76	        opened: Vec<HoldKey>,
77	        completed: Vec<(HoldKey, Vec<ToolCall>)>,
78	        reports: Vec<ReportEntry>,
79	    },
80	    /// The end marker; every later record is dropped (D4).
81	    End(Frame),
82	    /// An upstream error record (D17).
83	    UpstreamError(Frame),
