103	/// One wire protocol. The interceptor owns ordering, limits and failure handling; a protocol owns
104	/// classification, assembly and rewriting.
105	pub(crate) trait Protocol: Send {
106	    fn step(&mut self, rec: Record, verdicts: &Verdicts) -> Result<Step, StepError>;
107	    /// Holds that opened and did not complete. At the end of the stream these are truncated.
