190	/// serde_json has no arbitrary_precision: an integer beyond u64/i64 becomes an f64 and is rounded,
191	/// so a decider reading the parsed value would see a different number than a client that keeps the
192	/// exact integer (I1). Bodies check the whole value; streams check the raw entries of kind Other.
193	///
194	/// `Malformed("lossy_number")` for a number outside u64/i64 that is an integral f64 with magnitude of 2^53 or more.
195	pub(crate) fn check_numbers(v: &Value) -> Result<(), Malformed> {
196	    match v {
197	        Value::Number(n) => match n.as_f64() {
198	            Some(f) if !n.is_u64() && !n.is_i64() && f.fract() == 0.0 && f.abs() >= 9_007_199_254_740_992.0 => Err(Malformed("lossy_number")),
199	            _ => Ok(()),
200	        },
201	        Value::Array(a) => a.iter().try_for_each(check_numbers),
202	        Value::Object(o) => o.values().try_for_each(check_numbers),
203	        _ => Ok(()),
204	    }
205	}
206	
207	/// A JSON integer literal in `0..=max` (spec § 4.2). serde_json reads `0.0` and `1e0` as floats,
208	/// so `is_u64` already excludes them.
209	pub(crate) fn index_of(v: Option<&Value>, max: u64) -> Result<u32, Malformed> {
210	    match v {
211	        Some(Value::Number(n)) if n.is_u64() => n.as_u64().filter(|i| *i <= max).and_then(|i| u32::try_from(i).ok()).ok_or(Malformed("index")),
212	        _ => Err(Malformed("index")),
213	    }
214	}
215	
216	pub(crate) fn opt_str(v: Option<&Value>, what: &'static str) -> Result<Option<String>, Malformed> {
217	    match v {
218	        None | Some(Value::Null) => Ok(None),
219	        Some(Value::String(s)) => Ok(Some(s.clone())),
220	        Some(_) => Err(Malformed(what)),
221	    }
222	}
223	
224	pub(crate) fn opt_obj<'a>(v: Option<&'a Value>, what: &'static str) -> Result<Option<&'a Map<String, Value>>, Malformed> {
225	    match v {
226	        None | Some(Value::Null) => Ok(None),
227	        Some(Value::Object(m)) => Ok(Some(m)),
228	        Some(_) => Err(Malformed(what)),
229	    }
230	}
231	
232	#[cfg(test)]
233	mod tests {
234	    use super::*;
235	    use serde_json::json;
236	
237	    #[test]
238	    fn a_plain_record_parses() {
239	        assert_eq!(parse_strict(br#"{"a":[1,"x",null,true,{"b":2.5}]}"#).unwrap(), json!({"a":[1,"x",null,true,{"b":2.5}]}));
240	    }
241	
242	    #[test]
243	    fn duplicate_keys_are_malformed_at_any_depth() {
244	        assert!(parse_strict(br#"{"a":1,"a":2}"#).is_err());
245	        assert!(parse_strict(br#"{"choices":[{"delta":{"tool_calls":[]},"delta":{"content":"hi"}}]}"#).is_err());
246	        assert!(parse_strict(br#"[{"x":{"y":1,"y":1}}]"#).is_err());
247	    }
248	
249	    #[test]
250	    fn prototype_keys_are_malformed() {
251	        for k in ["__proto__", "constructor", "prototype"] {
252	            assert!(parse_strict(format!(r#"{{"choices":[{{"{k}":{{}}}}]}}"#).as_bytes()).is_err(), "{k}");
253	        }
254	    }
255	
256	    #[test]
