281	    #[test]
282	    fn escaped_duplicates_and_escaped_prototype_keys_are_malformed() {
283	        assert!(parse_strict(br#"{"tool_calls":[],"tool_calls":[{}]}"#).is_err());
284	        assert!(parse_strict(br#"{"tool\u005fcalls":[],"tool_calls":[{}]}"#).is_err());
285	        assert!(parse_strict(br#"{"__proto__":{}}"#).is_err());
286	        assert!(parse_strict(br#"{"\u005f_proto__":{}}"#).is_err());
287	    }
288	
289	    #[test]
290	    fn non_json_and_trailing_bytes_are_malformed() {
291	        for bad in [&b"NaN"[..], b"{\"a\":NaN}", b"{\"a\":Infinity}", b"{} {}", b"{\"a\":1", b"", b"\"\\ud800\""] {
292	            assert!(parse_strict(bad).is_err(), "{:?}", String::from_utf8_lossy(bad));
