299	        let v = parse_strict(br#"{"tool\u005fcalls":[1]}"#).unwrap();
300	        assert_eq!(v, json!({"tool_calls":[1]}));
301	    }
302	
303	    /// Tool argument data is the application's, not the envelope's: a PascalCase or
304	    /// `constructor` key there is a legitimate argument, but a duplicate or `__proto__` is not.
305	    #[test]
306	    fn application_data_skips_the_envelope_key_rules_but_keeps_the_rest() {
307	        for ok in [
308	            r#"{"Id":1,"Name":"Alice","Type":"pdf","Content":"x","Input":1,"Index":0,"Role":"r","Message":"m"}"#,
309	            r#"{"constructor":1,"prototype":{"Tool_Calls":[{"Id":2}]}}"#,
310	        ] {
311	            assert!(parse_value_strict(ok.as_bytes()).is_ok(), "{ok}");
312	        }
313	        for bad in [
314	            r#"{"a":1,"a":2}"#,
315	            r#"{"x":{"Id":1,"Id":2}}"#,
316	            r#"{"__proto__":{}}"#,
317	            r#"{"x":[{"\u005f_proto__":1}]}"#,
318	            r#"{"a":NaN}"#,
