334	        }
335	        for bad in [
336	            r#"{"content":[{"input":{"a":1,"a":2}}]}"#,
337	            r#"{"content":[{"input":{"x":{"__proto__":1}}}]}"#,
338	            r#"{"tools":[{"input_schema":{"Name":1,"Name":2}}]}"#,
339	            r#"{"Input":{}}"#,
340	            r#"{"input":{},"constructor":1}"#,
341	            r#"{"content":[{"Content":[]}]}"#,
342	        ] {
343	            assert!(parse_strict(bad.as_bytes()).is_err(), "{bad}");
344	        }
345	    }
346	
347	    #[test]
348	    fn index_must_be_a_plain_integer_in_range() {
349	        assert_eq!(index_of(Some(&json!(0)), MAX_OPENAI_INDEX).unwrap(), 0);
350	        assert_eq!(index_of(Some(&json!(127)), MAX_OPENAI_INDEX).unwrap(), 127);
351	        let floaty = parse_strict(b"[0.0, 1e0, -1, true, \"0\", 128]").unwrap();
352	        for v in floaty.as_array().unwrap() {
