361	        assert_eq!(opt_str(Some(&json!(null)), "x").unwrap(), None);
362	        assert_eq!(opt_str(Some(&json!("a")), "x").unwrap(), Some("a".to_owned()));
363	        assert!(opt_str(Some(&json!(1)), "x").is_err());
364	        assert!(opt_obj(Some(&json!({})), "x").unwrap().is_some());
365	        assert!(opt_obj(Some(&json!([])), "x").is_err());
366	    }
