1	// SPDX-License-Identifier: Apache-2.0
2	//! What the two wire protocols share (spec § 4, D12): the `Protocol` trait, verdicts and frames.
3	
4	use std::collections::BTreeMap;
5	
6	use bytes::Bytes;
7	use serde_json::Value;
8	
9	use crate::json::Malformed;
10	use crate::report::ReportEntry;
11	use crate::sse::Record;
12	use crate::types::{BlockCode, Decision, HoldKey, ToolCall};
13	
14	/// A violation of the canonical assembly form (spec § 4.3). Always a stream-level `on_failure`.
15	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
16	pub(crate) struct Deviation(pub &'static str);
17	
18	/// The longest tool-call id or name accepted, in bytes. Real ids and names are under 100 bytes. A
19	/// longer one is `Deviation("long_identifier")`: a completed block or call keeps its name for the
20	/// stream's life, so an unbounded one would be retained outside the held-byte accounting.
21	pub(crate) const MAX_IDENTIFIER_BYTES: usize = 1024;
22	
23	/// What a hold's calls are allowed to do once released.
24	#[derive(Debug, Clone, PartialEq, Eq)]
25	pub(crate) enum Verdict {
26	    /// Every call allowed: frames are released unchanged.
27	    AllowAll,
28	    /// One decision per call, in the hold's call order.
29	    PerCall(Vec<Decision>),
30	    /// Every call of the hold blocked, including calls not assembled yet.
31	    BlockAll(BlockCode),
32	    /// Observe mode: released unchanged and not enforced (§ 5.3).
33	    PassThrough,
34	}
35	
36	impl Verdict {
37	    pub(crate) fn blocks_any(&self) -> bool {
38	        match self {
39	            Verdict::AllowAll | Verdict::PassThrough => false,
40	            Verdict::BlockAll(_) => true,
41	            Verdict::PerCall(d) => d.iter().any(|d| !d.is_allow()),
42	        }
43	    }
44	
45	    /// The block code of the call in `slot` (its index within the hold), or `None` when allowed.
46	    pub(crate) fn block_code(&self, slot: usize) -> Option<BlockCode> {
47	        match self {
48	            Verdict::AllowAll | Verdict::PassThrough => None,
49	            Verdict::BlockAll(c) => Some(*c),
50	            Verdict::PerCall(d) => match d.get(slot) {
51	                Some(Decision::Block { code }) => Some(*code),
52	                Some(_) => None,
53	                None => Some(BlockCode::DeciderError), // D18: a missing decision is a block
54	            },
55	        }
56	    }
57	}
58	
59	pub(crate) type Verdicts = BTreeMap<HoldKey, Verdict>;
60	
61	/// One classified record, waiting in the queue or about to be released.
62	pub(crate) struct Frame {
63	    /// The validated Anthropic event name; `None` for OpenAI (P-1).
64	    pub event: Option<&'static str>,
65	    /// The original payload bytes, re-framed unchanged when nothing in it is blocked (D23).
66	    pub payload: Vec<u8>,
67	    /// The parsed payload; `None` only for OpenAI's `[DONE]`.
68	    pub value: Option<Value>,
69	    /// The holds this frame carries data of (D12). Sorted and without duplicates.
70	    pub touches: Vec<HoldKey>,
71	}
72	
73	pub(crate) enum Step {
74	    Frame {
75	        frame: Frame,
76	        opened: Vec<HoldKey>,
77	        completed: Vec<(HoldKey, Vec<ToolCall>)>,
78	        reports: Vec<ReportEntry>,
79	    },
80	    /// The end marker; every later record is dropped (D4).
81	    End(Frame),
82	    /// An upstream error record (D17).
83	    UpstreamError(Frame),
84	}
85	
86	pub(crate) enum StepError {
87	    Malformed,
88	    Deviation(&'static str),
89	}
90	
91	impl From<Malformed> for StepError {
92	    fn from(_: Malformed) -> Self {
93	        StepError::Malformed
94	    }
95	}
96	
97	impl From<Deviation> for StepError {
98	    fn from(d: Deviation) -> Self {
99	        StepError::Deviation(d.0)
100	    }
101	}
102	
103	/// One wire protocol. The interceptor owns ordering, limits and failure handling; a protocol owns
104	/// classification, assembly and rewriting.
105	pub(crate) trait Protocol: Send {
106	    fn step(&mut self, rec: Record, verdicts: &Verdicts) -> Result<Step, StepError>;
107	    /// Holds that opened and did not complete. At the end of the stream these are truncated.
108	    fn incomplete(&self) -> Vec<HoldKey>;
109	    /// The bytes for one released frame under the verdicts. May be empty (a dropped frame) or
110	    /// several frames (a notice first).
111	    fn release(&mut self, frame: Frame, verdicts: &Verdicts) -> Vec<Bytes>;
112	    /// Notices still owed at the end of a stream that has no end marker.
113	    fn closing(&mut self, verdicts: &Verdicts) -> Vec<Bytes>;
114	    /// (position, name) of the calls known so far for a hold, for reports of a `BlockAll` hold.
115	    fn known_calls(&self, hold: HoldKey) -> Vec<(u32, String)>;
116	    /// Pass-through framing, with no classification (P-4).
117	    fn unframed(&self, rec: Record) -> Bytes;
118	    /// The argument and raw-entry bytes the protocol still holds, measured exactly. Tests only.
119	    #[cfg(test)]
120	    fn retained(&self) -> usize;
121	}
122	
123	/// The serialized size of one raw entry, as the decider would see it.
124	pub(crate) fn raw_len(raw: &Value) -> usize {
125	    serde_json::to_vec(raw).expect("a Value always serializes").len()
126	}
127	
128	/// The serialized size of retained raw entries.
129	#[cfg(test)]
130	pub(crate) fn raws_len(raws: &[Value]) -> usize {
131	    raws.iter().map(raw_len).sum()
132	}
133

1	// SPDX-License-Identifier: Apache-2.0
2	//! The shapes the SMA-747 specs share (spec § 4.1).
3	//!
4	//! Every type is `#[non_exhaustive]`: SMA-752 and SMA-754 add variants, and that must not be a
5	//! breaking change. These types move to `paigasus-kernel` with SMA-752, when a binding needs
6	//! them (spec D1).
7	
8	/// Which wire shape a tool call came from.
9	#[non_exhaustive]
10	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
11	pub enum ToolCallKind {
12	    /// OpenAI `tool_calls[]` of type `function`.
13	    Function,
14	    /// OpenAI `tool_calls[]` of type `custom`.
15	    Custom,
16	    /// OpenAI's legacy `function_call` field (the `functions` API).
17	    LegacyFunctionCall,
18	    /// An Anthropic `tool_use` content block.
19	    AnthropicToolUse,
20	    /// Any other tool-call shape. Held and decided, never passed unchecked (fail closed).
21	    Other,
22	}
23	
24	impl ToolCallKind {
25	    /// A stable lower-snake label, for reports and tests.
26	    #[must_use]
27	    pub fn as_str(self) -> &'static str {
28	        match self {
29	            ToolCallKind::Function => "function",
30	            ToolCallKind::Custom => "custom",
31	            ToolCallKind::LegacyFunctionCall => "legacy_function_call",
32	            ToolCallKind::AnthropicToolUse => "tool_use",
33	            ToolCallKind::Other => "other",
34	        }
35	    }
36	}
37	
38	/// One complete tool call, as the decider sees it.
39	///
40	/// `arguments` holds (spec § 4.1): the concatenated `function.arguments` string (Function,
41	/// LegacyFunctionCall); `custom.input` (Custom); the concatenated `partial_json` of an Anthropic
42	/// stream, or the compact JSON of a non-stream `input` (AnthropicToolUse); and the raw JSON of the
43	/// whole entry, as a JSON array of its fragments (Other).
44	///
45	/// `Debug` prints `arguments`, which are model output and may carry secrets. Never log a
46	/// `ToolCall` with `{:?}`; log its sanitized name only (spec § 4.5).
47	#[non_exhaustive]
48	#[derive(Debug, Clone, PartialEq, Eq)]
49	pub struct ToolCall {
50	    /// OpenAI choice index. Always 0 for Anthropic.
51	    pub choice: u32,
52	    /// The tool-call index (OpenAI) or the content-block index (Anthropic), as the upstream sent it.
53	    pub position: u32,
54	    /// The upstream's call id. `None` for a legacy `function_call`.
55	    pub id: Option<String>,
56	    pub name: String,
57	    pub kind: ToolCallKind,
58	    pub arguments: String,
59	}
60	
61	/// The decider's answer for one call.
62	#[non_exhaustive]
63	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
64	pub enum Decision {
65	    Allow,
66	    Block { code: BlockCode },
67	}
68	
69	impl Decision {
70	    #[must_use]
71	    pub fn is_allow(self) -> bool {
72	        matches!(self, Decision::Allow)
73	    }
74	}
75	
76	/// Why a call was blocked.
77	#[non_exhaustive]
78	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
79	pub enum BlockCode {
80	    /// A policy refused it (SMA-752).
81	    Policy,
82	    /// A detector finding refused it (SMA-754).
83	    Detector,
84	    /// A hold exceeded `max_held_bytes` or `max_hold_secs` (D13, D14).
85	    HoldLimit,
86	    /// A record or the assembly was not in canonical form (D5–D9).
87	    Malformed,
88	    /// The stream ended before the call was complete (D10, D11).
89	    Truncated,
90	    /// The decider failed, timed out, or returned the wrong number of decisions (D18).
91	    DeciderError,
92	}
93	
94	impl BlockCode {
95	    /// The kebab-case label used in the notice and in reports (§ 4.5).
96	    #[must_use]
97	    pub fn as_kebab(self) -> &'static str {
98	        match self {
99	            BlockCode::Policy => "policy",
100	            BlockCode::Detector => "detector",
101	            BlockCode::HoldLimit => "hold-limit",
102	            BlockCode::Malformed => "malformed",
103	            BlockCode::Truncated => "truncated",
104	            BlockCode::DeciderError => "decider-error",
105	        }
106	    }
107	}
108	
109	/// How a decision was reached (§ 5.3).
110	#[non_exhaustive]
111	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
112	pub enum Basis {
113	    Decider,
114	    OnFailure,
115	}
116	
117	impl Basis {
118	    #[must_use]
119	    pub fn as_str(self) -> &'static str {
120	        match self {
121	            Basis::Decider => "decider",
122	            Basis::OnFailure => "on_failure",
123	        }
124	    }
125	}
126	
127	/// One hold: an OpenAI choice, or an Anthropic content block (D10, D11).
128	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
129	pub enum HoldKey {
130	    Choice(u32),
131	    Block(u32),
132	}
133	
134	/// Which provider wire format a stream or body uses.
135	#[non_exhaustive]
136	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
137	pub enum Format {
138	    OpenAiChat,
139	    AnthropicMessages,
140	}
141	
142	#[cfg(test)]
143	mod tests {
144	    use super::*;
145	
146	    #[test]
147	    fn block_codes_have_stable_kebab_labels() {
148	        let all = [
149	            BlockCode::Policy,
150	            BlockCode::Detector,
151	            BlockCode::HoldLimit,
152	            BlockCode::Malformed,
153	            BlockCode::Truncated,
154	            BlockCode::DeciderError,
155	        ];
156	        let labels: Vec<&str> = all.iter().map(|c| c.as_kebab()).collect();
157	        assert_eq!(labels, ["policy", "detector", "hold-limit", "malformed", "truncated", "decider-error"]);
158	    }
159	
160	    #[test]
161	    fn only_allow_is_allow() {
162	        assert!(Decision::Allow.is_allow());
163	        assert!(!Decision::Block { code: BlockCode::Policy }.is_allow());
164	    }
165	
166	    #[test]
167	    fn kinds_and_bases_have_labels() {
168	        assert_eq!(ToolCallKind::LegacyFunctionCall.as_str(), "legacy_function_call");
169	        assert_eq!(ToolCallKind::AnthropicToolUse.as_str(), "tool_use");
170	        assert_eq!(Basis::OnFailure.as_str(), "on_failure");
171	    }
172	
173	    #[test]
174	    fn hold_keys_order_choices_before_blocks() {
175	        let mut keys = vec![HoldKey::Block(0), HoldKey::Choice(1), HoldKey::Choice(0)];
176	        keys.sort();
177	        assert_eq!(keys, [HoldKey::Choice(0), HoldKey::Choice(1), HoldKey::Block(0)]);
178	    }
179	}
