1	// SPDX-License-Identifier: Apache-2.0
2	//! Strict JSON (spec D5).
3	//!
4	//! A record that parses everywhere but means different things in different clients is worse than
5	//! one that fails to parse. serde and JavaScript keep the last of two duplicate keys, Go's
6	//! `encoding/json` merges struct-typed duplicates, and Go and Newtonsoft match field names
7	//! case-insensitively. JavaScript gives `__proto__` meaning. Rejecting all of these costs nothing
8	//! on a conforming upstream.
9	
10	use std::collections::HashSet;
11	use std::fmt;
12	
13	use serde::de::{self, DeserializeSeed, MapAccess, SeqAccess, Visitor};
14	use serde_json::{Map, Number, Value};
15	
16	/// A record the gateway cannot classify with certainty. The label is for tests and logs only;
17	/// it never reaches a metric label with a value from the record.
18	#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
19	#[error("malformed record: {0}")]
20	pub struct Malformed(pub &'static str);
21	
22	pub(crate) const MAX_OPENAI_INDEX: u64 = 127;
23	pub(crate) const MAX_ANTHROPIC_INDEX: u64 = 4095;
24	
25	/// Keys the classifiers read, in every format. A key that folds to one of these without being
26	/// byte-equal to it is a case-folding differential.
27	const CLASSIFIER_KEYS: &[&str] = &[
28	    "arguments",
29	    "choices",
30	    "chunk",
31	    "content",
32	    "content_block",
33	    "custom",
34	    "delta",
35	    "error",
36	    "finish_reason",
37	    "function",
38	    "function_call",
39	    "functions",
40	    "id",
41	    "index",
42	    "input",
43	    "input_schema",
44	    "logprobs",
45	    "message",
46	    "messages",
47	    "name",
48	    "parameters",
49	    "partial_json",
50	    "role",
51	    "stop_reason",
52	    "tool_call_id",
53	    "tool_calls",
54	    "tool_use_id",
55	    "tools",
56	    "type",
57	    "usage",
58	];
59	
60	const PROTOTYPE_KEYS: &[&str] = &["__proto__", "constructor", "prototype"];
61	
62	fn fold(s: &str) -> String {
63	    s.chars()
64	        .flat_map(|c| match c {
65	            '\u{0130}' | '\u{0131}' => 'i'.to_lowercase(),
66	            '\u{017F}' => 's'.to_lowercase(),
67	            '\u{212A}' => 'k'.to_lowercase(),
68	            c => c.to_lowercase(),
69	        })
70	        .collect()
71	}
72	
73	fn check_key(k: &str) -> Result<(), &'static str> {
74	    if PROTOTYPE_KEYS.contains(&k) {
75	        return Err("prototype_key");
76	    }
77	    if k.is_ascii() && k.bytes().all(|b| !b.is_ascii_uppercase()) {
78	        return Ok(()); // already folded; equal to a classifier key only if byte-equal
79	    }
80	    let folded = fold(k);
81	    if CLASSIFIER_KEYS.iter().any(|c| *c != k && folded == *c) {
82	        return Err("case_folded_key");
83	    }
84	    Ok(())
85	}
86	
87	/// Parse one record, body or request strictly. Envelope keys get every rule; the value of a
88	/// `DATA_KEYS` key gets the `parse_value_strict` rules.
89	pub(crate) fn parse_strict(bytes: &[u8]) -> Result<Value, Malformed> {
90	    parse_with(bytes, Mode::Envelope)
91	}
92	
93	/// Parse tool argument data strictly (spec D5): JSON validity, no non-finite number, no duplicate
94	/// key and no `__proto__` key, at every depth. The envelope key rules (case-folded classifier keys,
95	/// `constructor`, `prototype`) do not apply: the classifiers never read inside argument data, and
96	/// a tool may well take an argument called `Id` or `constructor`.
97	pub(crate) fn parse_value_strict(bytes: &[u8]) -> Result<Value, Malformed> {
98	    parse_with(bytes, Mode::Data)
99	}
100	
101	/// Keys whose value is tool argument or schema data, never envelope: an Anthropic `tool_use`
102	/// `input`, a request's `tools[].function.parameters` (and legacy `functions[].parameters`), and an
103	/// Anthropic `tools[].input_schema`. Below one of these keys, `parse_strict` applies the
104	/// `parse_value_strict` rules. OpenAI arguments are JSON strings, so they never reach this list.
105	const DATA_KEYS: &[&str] = &["input", "input_schema", "parameters"];
106	
107	#[derive(Clone, Copy, PartialEq, Eq)]
108	enum Mode {
109	    Envelope,
110	    Data,
111	}
112	
113	fn parse_with(bytes: &[u8], mode: Mode) -> Result<Value, Malformed> {
114	    let mut de = serde_json::Deserializer::from_slice(bytes);
115	    let value = Strict(mode).deserialize(&mut de).map_err(|_| Malformed("json"))?;
116	    de.end().map_err(|_| Malformed("trailing"))?;
117	    Ok(value)
118	}
119	
120	struct Strict(Mode);
121	
122	impl<'de> DeserializeSeed<'de> for Strict {
123	    type Value = Value;
124	    fn deserialize<D: de::Deserializer<'de>>(self, d: D) -> Result<Value, D::Error> {
125	        d.deserialize_any(StrictVisitor(self.0))
126	    }
127	}
128	
129	struct StrictVisitor(Mode);
130	
131	impl<'de> Visitor<'de> for StrictVisitor {
132	    type Value = Value;
133	
134	    fn expecting(&self, f: &mut fmt::Formatter) -> fmt::Result {
135	        f.write_str("a JSON value")
136	    }
137	    fn visit_bool<E: de::Error>(self, v: bool) -> Result<Value, E> {
138	        Ok(Value::Bool(v))
139	    }
140	    fn visit_i64<E: de::Error>(self, v: i64) -> Result<Value, E> {
141	        Ok(Value::Number(v.into()))
142	    }
143	    fn visit_u64<E: de::Error>(self, v: u64) -> Result<Value, E> {
144	        Ok(Value::Number(v.into()))
145	    }
146	    fn visit_f64<E: de::Error>(self, v: f64) -> Result<Value, E> {
147	        Number::from_f64(v).map(Value::Number).ok_or_else(|| E::custom("non-finite number"))
148	    }
149	    fn visit_str<E: de::Error>(self, v: &str) -> Result<Value, E> {
150	        Ok(Value::String(v.to_owned()))
151	    }
152	    fn visit_string<E: de::Error>(self, v: String) -> Result<Value, E> {
153	        Ok(Value::String(v))
154	    }
155	    fn visit_unit<E: de::Error>(self) -> Result<Value, E> {
156	        Ok(Value::Null)
157	    }
158	    fn visit_none<E: de::Error>(self) -> Result<Value, E> {
159	        Ok(Value::Null)
160	    }
161	    fn visit_seq<A: SeqAccess<'de>>(self, mut seq: A) -> Result<Value, A::Error> {
162	        let mut out = Vec::new();
163	        while let Some(v) = seq.next_element_seed(Strict(self.0))? {
164	            out.push(v);
165	        }
166	        Ok(Value::Array(out))
167	    }
168	    fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> Result<Value, A::Error> {
169	        let mut out = Map::new();
170	        let mut seen = HashSet::new();
171	        while let Some(k) = map.next_key::<String>()? {
172	            let child = match self.0 {
173	                Mode::Envelope => {
174	                    check_key(&k).map_err(de::Error::custom)?;
175	                    if DATA_KEYS.contains(&k.as_str()) { Mode::Data } else { Mode::Envelope }
176	                }
177	                Mode::Data if k == "__proto__" => return Err(de::Error::custom("prototype_key")),
178	                Mode::Data => Mode::Data,
179	            };
180	            if !seen.insert(k.clone()) {
181	                return Err(de::Error::custom("duplicate key"));
182	            }
183	            let v = map.next_value_seed(Strict(child))?;
184	            out.insert(k, v);
185	        }
186	        Ok(Value::Object(out))
187	    }
188	}
189	
190	/// serde_json has no arbitrary_precision: an integer beyond u64/i64 becomes an f64 and is rounded,
191	/// so a decider reading the parsed value would see a different number than a client that keeps the
192	/// exact integer (I1). Bodies check the whole value; streams check the raw entries of kind Other.
193	///
194	/// `Malformed("lossy_number")` for a number outside u64/i64 that is an integral f64 with magnitude of 2^53 or more.
195	pub(crate) fn check_numbers(v: &Value) -> Result<(), Malformed> {
196	    match v {
197	        Value::Number(n) => match n.as_f64() {
198	            Some(f) if !n.is_u64() && !n.is_i64() && f.fract() == 0.0 && f.abs() >= 9_007_199_254_740_992.0 => Err(Malformed("lossy_number")),
199	            _ => Ok(()),
200	        },
201	        Value::Array(a) => a.iter().try_for_each(check_numbers),
202	        Value::Object(o) => o.values().try_for_each(check_numbers),
203	        _ => Ok(()),
204	    }
205	}
206	
207	/// A JSON integer literal in `0..=max` (spec § 4.2). serde_json reads `0.0` and `1e0` as floats,
208	/// so `is_u64` already excludes them.
209	pub(crate) fn index_of(v: Option<&Value>, max: u64) -> Result<u32, Malformed> {
210	    match v {
211	        Some(Value::Number(n)) if n.is_u64() => n.as_u64().filter(|i| *i <= max).and_then(|i| u32::try_from(i).ok()).ok_or(Malformed("index")),
212	        _ => Err(Malformed("index")),
213	    }
214	}
215	
216	pub(crate) fn opt_str(v: Option<&Value>, what: &'static str) -> Result<Option<String>, Malformed> {
217	    match v {
218	        None | Some(Value::Null) => Ok(None),
219	        Some(Value::String(s)) => Ok(Some(s.clone())),
220	        Some(_) => Err(Malformed(what)),
221	    }
222	}
223	
224	pub(crate) fn opt_obj<'a>(v: Option<&'a Value>, what: &'static str) -> Result<Option<&'a Map<String, Value>>, Malformed> {
225	    match v {
226	        None | Some(Value::Null) => Ok(None),
227	        Some(Value::Object(m)) => Ok(Some(m)),
228	        Some(_) => Err(Malformed(what)),
229	    }
230	}
