645	    fn drain(i: &mut Interceptor, pending: &mut Vec<Action>, r: &mut Run, decide: &Decider<'_>, now: Instant) {
646	        while !pending.is_empty() {
647	            for a in std::mem::take(pending) {
648	                match a {
649	                    Action::Emit(b) => r.out.push_str(std::str::from_utf8(&b).unwrap()),
650	                    Action::Decide { hold, calls } => {
651	                        r.decides.push((hold, calls.clone()));
652	                        if let Some(res) = decide(&calls) {
653	                            pending.extend(i.decided(hold, res, now));
654	                        }
655	                    }
656	                    Action::Count(m) => r.counts.push(m),
657	                    Action::Wake(_) => {}
658	                }
659	            }
660	        }
661	    }
