1	// SPDX-License-Identifier: Apache-2.0
2	//! The OpenAI Chat Completions streaming protocol (spec § 4.2–§ 4.4, D10, D12, D20).
3	//!
4	//! Three shapes are a deviation only inside a call of choice 0: while a call is open, and in the
5	//! record that opens one ([`in_call`]). A raising client drops the stream there and holds a strict
6	//! prefix of the call, while the decider would still hold all of it.
7	//!
8	//! - A chunk without a `choices` key (`chunk_without_choices`, spec § 2.2 P-a): openai-python
9	//!   and openai-node read `chunk.choices`.
10	//! - A choice entry without a `delta` key, in any position (`choice_without_delta`, P-b):
11	//!   openai-python reads `choice.delta`, and LangChain raises `KeyError: 'delta'`. The entry of
12	//!   choice 0 with a `finish_reason` may omit `delta`.
13	//! - An array in a delta outside the `tool_calls` array itself (`array_outside_tool_calls`, spec
14	//!   § 5.7): under any other delta key, or under any key of a tool-call entry, its `function` and
15	//!   `custom` objects included, at any depth. openai-python's `accumulate_delta` raises when a
16	//!   later list does not merge into an earlier one (`{"foo":[{"index":0}]}`, then `{"foo":[1]}`).
17	//!
18	//! `"choices":[]` is keyed, so the final usage chunk is conforming. The record that opens a call
19	//! counts: a raise later in that record cuts the call after its first fragment (spec § 5.2).
20	
21	use std::collections::BTreeMap;
22	
23	use bytes::Bytes;
24	use serde_json::{Map, Value, json};
25	
26	use crate::json::parse_strict;
27	use crate::openai::assembly::{self, Check, ChoiceAssembly};
28	use crate::openai::classify::{self, ChoiceView, Chunk};
29	use crate::protocol::{Frame, Protocol, Step, StepError, Verdict, Verdicts};
30	use crate::report::notice_line;
31	use crate::sse::{self, Record};
32	use crate::types::HoldKey;
33	
34	/// The upstream fields a notice chunk copies, in upstream order. `object` is not copied: a notice
35	/// chunk always says `chat.completion.chunk`, or openai-python would skip it.
36	const META_KEYS: [&str; 4] = ["id", "created", "model", "system_fingerprint"];
37	
38	#[derive(Default)]
39	struct ChoiceState {
40	    asm: ChoiceAssembly,
41	    hold_open: bool,
42	    finished: bool,
43	    has_text: bool,
44	    notice_done: bool,
45	    /// The (position, name) of the calls handed to the decider, in hold order. Never their
46	    /// arguments: a finished choice keeps none.
47	    calls: Vec<(u32, String)>,
48	}
49	
50	pub(crate) struct OpenAiStream {
51	    choices: BTreeMap<u32, ChoiceState>,
52	    meta: Map<String, Value>,
53	    /// The most an observed choice may retain (D13, § 5.3).
54	    cap: usize,
55	}
56	
57	impl Default for OpenAiStream {
58	    fn default() -> Self {
59	        Self::with_cap(crate::limits::Limits::defaults().max_held_bytes)
60	    }
61	}
62	
63	impl OpenAiStream {
64	    pub(crate) fn with_cap(cap: usize) -> Self {
65	        OpenAiStream {
66	            choices: BTreeMap::new(),
67	            meta: Map::new(),
68	            cap,
69	        }
70	    }
71	}
72	
73	/// The scalar (string or number) `META_KEYS` fields of a record. A non-scalar value is skipped.
74	fn meta_of(v: &Value) -> Map<String, Value> {
75	    let mut m = Map::new();
76	    if let Value::Object(top) = v {
77	        for k in META_KEYS {
78	            if let Some(x @ (Value::String(_) | Value::Number(_))) = top.get(k) {
79	                m.insert(k.to_owned(), x.clone());
80	            }
81	        }
82	    }
83	    m
84	}
85	
86	fn notice_chunk(meta: &Map<String, Value>, choice: u32, text: &str) -> Bytes {
87	    let mut m = Map::new();
88	    for (k, v) in meta {
89	        m.insert(k.clone(), v.clone());
90	        if k == "id" {
91	            m.insert("object".to_owned(), classify::CHUNK_OBJECT.into());
92	        }
93	    }
94	    m.entry("object").or_insert_with(|| classify::CHUNK_OBJECT.into());
95	    m.insert("choices".to_owned(), json!([{"index": choice, "delta": {"content": text}, "finish_reason": null}]));
96	    sse::frame(None, &serde_json::to_vec(&Value::Object(m)).expect("a Value always serializes"))
97	}
98	
99	impl ChoiceState {
100	    /// The (position, name) of every call the hold knows.
101	    fn known(&self) -> Vec<(u32, String)> {
102	        if self.calls.is_empty() { self.asm.names() } else { self.calls.clone() }
103	    }
104	
105	    fn notice_text(&self, verdict: &Verdict) -> String {
106	        let lines: Vec<String> = self
107	            .known()
108	            .iter()
109	            .enumerate()
110	            .filter_map(|(slot, (_, name))| verdict.block_code(slot).map(|code| notice_line(name, code)))
111	            .collect();
112	        let body = if lines.is_empty() {
113	            notice_line("unknown", verdict.block_code(0).unwrap_or(crate::types::BlockCode::Malformed))
114	        } else {
115	            lines.join("\n")
116	        };
117	        if self.has_text { format!("\n\n{body}") } else { body }
118	    }
119	
120	    fn allowed_left(&self, verdict: &Verdict) -> usize {
121	        (0..self.known().len()).filter(|slot| verdict.block_code(*slot).is_none()).count()
122	    }
123	}
124	
125	/// Whether a client raise at this record can cut a call of choice 0: a call is open, or this record
126	/// opens one (it carries tool data for choice 0). Every raise-shape rule uses this one predicate.
127	fn in_call(open_call: bool, choices: &[ChoiceView]) -> bool {
128	    open_call || choices.iter().any(|c| c.index == 0 && (!c.fragments.is_empty() || c.legacy.is_some()))
129	}
130	
131	impl Protocol for OpenAiStream {
132	    fn step(&mut self, rec: Record, verdicts: &Verdicts) -> Result<Step, StepError> {
133	        if rec.data == b"[DONE]" {
134	            return Ok(Step::End(Frame {
135	                event: None,
136	                payload: rec.data,
137	                value: None,
138	                touches: Vec::new(),
139	            }));
140	        }
141	        let value = parse_strict(&rec.data)?;
142	        let (choices, keyed) = match classify::chunk(&value)? {
143	            Chunk::UpstreamError => {
144	                return Ok(Step::UpstreamError(Frame {
145	                    event: None,
146	                    payload: rec.data,
147	                    value: Some(value),
148	                    touches: Vec::new(),
149	                }));
150	            }
151	            Chunk::Choices { choices, keyed } => (choices, keyed),
152	        };
153	        // Phase 1 checks the whole record and changes nothing. A deviation in any choice drops the
154	        // record, so no choice may have been changed by then: a hold marked open that the
155	        // interceptor never registered would wait for a verdict for ever.
156	        let empty = ChoiceAssembly::default();
157	        // The shapes at which a client raises (see the module doc).
158	        let in_call = in_call(self.choices.get(&0).is_some_and(|s| s.hold_open && !s.finished), &choices);
159	        if in_call && !keyed {
160	            return Err(StepError::Deviation("chunk_without_choices"));
161	        }
162	        let mut planned: Vec<Option<Check>> = Vec::with_capacity(choices.len());
163	        let mut new_choices = 0;
164	        for (position, cv) in choices.iter().enumerate() {
165	            if in_call && !cv.has_delta && !(cv.index == 0 && cv.finish_reason.is_some()) {
166	                return Err(StepError::Deviation("choice_without_delta"));
167	            }
168	            if in_call && cv.stray_array {
169	                return Err(StepError::Deviation("array_outside_tool_calls"));
170	            }
171	            let key = HoldKey::Choice(cv.index);
172	            let st = self.choices.get(&cv.index);
173	            if st.is_none() {
174	                if cv.index as usize != self.choices.len() + new_choices {
175	                    return Err(StepError::Deviation("choice_order"));
176	                }
177	                new_choices += 1;
178	            }
179	            let (finished, hold_open, asm) = st.map_or((false, false, &empty), |s| (s.finished, s.hold_open, &s.asm));
180	            let tools = !cv.fragments.is_empty() || cv.legacy.is_some();
181	            let undecided = !verdicts.contains_key(&key);
182	            let mut after = None;
183	            if tools {
184	                assembly::check_tool_choice(cv.index, position, &cv.fragments, cv.legacy.as_ref())?;
185	                if finished {
186	                    return Err(StepError::Deviation("late_fragment"));
187	                }
188	                if undecided {
189	                    after = Some(asm.check(&cv.fragments, cv.legacy.as_ref())?);
190	                }
191	            }
192	            if cv.finish_reason.is_some() {
193	                if finished {
194	                    return Err(StepError::Deviation("second_finish"));
195	                }
196	                if (hold_open || tools) && undecided {
197	                    asm.check_finish(&cv.fragments, cv.legacy.as_ref(), after.as_ref().unwrap_or(asm.state()))?;
198	                }
199	            }
200	            planned.push(after);
201	        }
202	        // Phase 2 applies the checked record. Only an accepted record updates the notice meta.
203	        for (k, v) in meta_of(&value) {
204	            self.meta.insert(k, v);
205	        }
206	        let (mut touches, mut opened, mut completed) = (Vec::new(), Vec::new(), Vec::new());
207	        for (cv, after) in choices.into_iter().zip(planned) {
208	            let key = HoldKey::Choice(cv.index);
209	            let st = self.choices.entry(cv.index).or_default();
210	            if cv.has_text {
211	                st.has_text = true;
212	            }
213	            if !cv.fragments.is_empty() || cv.legacy.is_some() {
214	                match (verdicts.get(&key), after) {
215	                    (None, Some(after)) => st.asm.commit(&cv.fragments, cv.legacy.as_ref(), after),
216	                    (Some(Verdict::PassThrough), _) => st.asm.observe(&cv.fragments, cv.legacy.as_ref(), self.cap),
217	                    _ => {}
218	                }
219	                if !st.hold_open {
220	                    st.hold_open = true;
221	                    opened.push(key);
222	                }
223	                touches.push(key);
224	            }
225	            if cv.finish_reason.is_some() {
226	                st.finished = true;
227	                if st.hold_open {
228	                    touches.push(key);
229	                    let finished = match verdicts.get(&key) {
230	                        // Phase 1 ran the same check on the same state, so this cannot fail.
231	                        None => Some(st.asm.finish(cv.index)?),
232	                        Some(Verdict::PassThrough) if !st.asm.overflowed() => st.asm.finish(cv.index).ok(),
233	                        Some(_) => None,
234	                    };
235	                    st.asm.drop_buffers();
236	                    if let Some(calls) = finished {
237	                        st.calls = calls.iter().map(|c| (c.position, c.name.clone())).collect();
238	                        completed.push((key, calls));
239	                    }
240	                }
241	            }
242	        }
243	        touches.sort();
244	        touches.dedup();
245	        Ok(Step::Frame {
246	            frame: Frame {
247	                event: None,
248	                payload: rec.data,
249	                value: Some(value),
250	                touches,
251	            },
252	            opened,
253	            completed,
254	            reports: Vec::new(),
255	        })
256	    }
257	
258	    fn incomplete(&self) -> Vec<HoldKey> {
259	        self.choices.iter().filter(|(_, s)| s.hold_open && !s.finished).map(|(c, _)| HoldKey::Choice(*c)).collect()
260	    }
261	
262	    fn release(&mut self, frame: Frame, verdicts: &Verdicts) -> Vec<Bytes> {
263	        let Some(mut value) = frame.value else {
264	            let mut out = self.closing(verdicts);
265	            out.push(sse::frame(None, &frame.payload));
266	            return out;
267	        };
268	        let blocking: Vec<u32> = frame
269	            .touches
270	            .iter()
271	            .filter_map(|k| match (k, verdicts.get(k)) {
272	                (HoldKey::Choice(c), Some(v)) if v.blocks_any() => Some(*c),
273	                _ => None,
274	            })
275	            .collect();
276	        if blocking.is_empty() {
277	            return vec![sse::frame(None, &frame.payload)];
278	        }
279	        let meta = meta_of(&value);
280	        let mut notices = Vec::new();
281	        if let Some(Value::Array(choices)) = value.get_mut("choices") {
282	            for ch in choices.iter_mut() {
283	                let idx = ch.get("index").and_then(Value::as_u64).and_then(|i| u32::try_from(i).ok()).unwrap_or(0);
284	                if let Some(v) = verdicts.get(&HoldKey::Choice(idx)).filter(|_| blocking.contains(&idx)) {
285	                    let st = self.choices.entry(idx).or_default();
286	                    if let Some(text) = rewrite_choice(ch, v, st) {
287	                        notices.push(notice_chunk(&meta, idx, &text));
288	                    }
289	                }
290	            }
291	        }
292	        // P-10: never drop the frame or a choice entry. openai-python finds a choice by list
293	        // position, so a missing first appearance would shift every later choice.
294	        notices.push(sse::frame(None, &serde_json::to_vec(&value).expect("a Value always serializes")));
295	        notices
296	    }
297	
298	    fn closing(&mut self, verdicts: &Verdicts) -> Vec<Bytes> {
299	        let mut out = Vec::new();
300	        for (idx, st) in &mut self.choices {
301	            let Some(v) = verdicts.get(&HoldKey::Choice(*idx)) else { continue };
302	            if st.hold_open && v.blocks_any() && !st.notice_done {
303	                st.notice_done = true;
304	                out.push(notice_chunk(&self.meta, *idx, &st.notice_text(v)));
305	            }
306	        }
307	        out
308	    }
309	
310	    fn known_calls(&self, hold: HoldKey) -> Vec<(u32, String)> {
311	        match hold {
312	            HoldKey::Choice(c) => self.choices.get(&c).map(ChoiceState::known).unwrap_or_default(),
313	            HoldKey::Block(_) => Vec::new(),
314	        }
315	    }
316	
317	    fn unframed(&self, rec: Record) -> Bytes {
318	        sse::frame(None, &rec.data)
319	    }
320	
321	    #[cfg(test)]
322	    fn retained(&self) -> usize {
323	        self.choices.values().map(|s| s.asm.retained()).sum()
324	    }
325	}
