327	/// Rewrite one choice entry in place (§ 4.4). Returns the notice text when this entry carries the
328	/// choice's `finish_reason` and the notice is still owed.
329	fn rewrite_choice(ch: &mut Value, verdict: &Verdict, st: &mut ChoiceState) -> Option<String> {
330	    let slots: Vec<u32> = st.known().iter().map(|(p, _)| *p).collect();
331	    let slot_of = |pos: u32| slots.iter().position(|p| *p == pos).unwrap_or(slots.len());
332	    let rank = |pos: u32| -> u32 { u32::try_from((0..slot_of(pos)).filter(|s| verdict.block_code(*s).is_none()).count()).expect("at most 128 calls per choice") };
333	    if let Some(Value::Object(delta)) = ch.get_mut("delta") {
334	        if let Some(Value::Array(tc)) = delta.get_mut("tool_calls") {
335	            tc.retain_mut(|e| {
336	                let pos = e.get("index").and_then(Value::as_u64).and_then(|i| u32::try_from(i).ok()).unwrap_or(0);
337	                if verdict.block_code(slot_of(pos)).is_some() {
338	                    return false;
339	                }
340	                e["index"] = rank(pos).into();
341	                true
342	            });
343	            if tc.is_empty() {
344	                delta.remove("tool_calls");
345	            }
346	        }
347	        if delta.contains_key("function_call") && verdict.block_code(0).is_some() {
348	            delta.remove("function_call");
349	        }
350	    }
351	    if let Value::Object(o) = ch {
352	        o.remove("logprobs");
353	    }
354	    let finish = ch.get("finish_reason").and_then(Value::as_str).map(str::to_owned)?;
355	    if st.allowed_left(verdict) == 0 && (finish == "tool_calls" || finish == "function_call") {
356	        ch["finish_reason"] = "stop".into();
357	    }
358	    if st.notice_done {
359	        return None;
360	    }
361	    st.notice_done = true;
362	    Some(st.notice_text(verdict))
363	}
