383	    /// Steps every record, then releases every frame under `verdict` for each completed hold.
384	    /// Returns the concatenated output and the completed calls.
385	    fn run(records: &[String], verdict: impl Fn(&[crate::types::ToolCall]) -> Verdict) -> (String, Vec<crate::types::ToolCall>) {
386	        let mut p = OpenAiStream::default();
387	        let mut verdicts = Verdicts::new();
388	        let mut frames = Vec::new();
389	        let mut calls = Vec::new();
390	        for r in records {
391	            match p.step(rec(r), &verdicts).ok().expect("canonical record") {
392	                Step::Frame { frame, completed, .. } => {
393	                    for (k, c) in completed {
394	                        verdicts.insert(k, verdict(&c));
395	                        calls.extend(c);
396	                    }
397	                    frames.push(frame);
398	                }
399	                Step::End(f) | Step::UpstreamError(f) => frames.push(f),
400	            }
401	        }
402	        let mut out = Vec::new();
403	        for f in frames {
404	            for b in p.release(f, &verdicts) {
405	                out.extend_from_slice(&b);
406	            }
407	        }
408	        for b in p.closing(&verdicts) {
409	            out.extend_from_slice(&b);
410	        }
411	        (String::from_utf8(out).unwrap(), calls)
412	    }
