1	// SPDX-License-Identifier: Apache-2.0
2	//! SSE framing (spec D2–D4).
3	//!
4	//! Input follows WHATWG HTML § 9.2.6 line splitting, with one difference: the last record is
5	//! dispatched at the end of the stream even without a blank line (D4), as `UsageScanner::finish`
6	//! does. Output is ALWAYS re-framed by [`frame`]: no upstream byte reaches the client unless the
7	//! record that carried it was classified (D3). So a BOM, a lax line or an unknown field cannot
8	//! smuggle a record past the classifier into a client that reads SSE differently.
9	//!
10	//! Unlike `UsageScanner`, nothing is ever skipped silently. A record over the cap becomes
11	//! [`SseItem::Oversized`], which the interceptor treats as a stream-level failure (D8).
12	
13	use bytes::Bytes;
14	
15	/// One dispatched SSE record.
16	#[derive(Debug, Clone, PartialEq, Eq)]
17	pub(crate) struct Record {
18	    pub event: Option<String>,
19	    /// The joined `data` lines, without the final `\n`. Never empty (P-2).
20	    pub data: Vec<u8>,
21	}
22	
23	#[derive(Debug, Clone, PartialEq, Eq)]
24	pub(crate) enum SseItem {
25	    Record(Record),
26	    /// A record passed `max_record_bytes`. Its bytes were discarded (P-3).
27	    Oversized,
28	}
29	
30	const BOM: &[u8] = b"\xEF\xBB\xBF";
31	
32	/// The SSE comment sent while anything is held (D15).
33	pub(crate) const KEEP_ALIVE: &[u8] = b": keep-alive\n\n";
34	
35	enum BomState {
36	    /// Bytes seen so far that could still be a BOM.
37	    Pending(Vec<u8>),
38	    Done,
39	}
40	
41	pub(crate) struct SseSplitter {
42	    max_record_bytes: usize,
43	    bom: BomState,
44	    line: Vec<u8>,
45	    /// Bytes in the current line, counted even while skipping.
46	    line_bytes: usize,
47	    after_cr: bool,
48	    record_bytes: usize,
49	    data: Vec<u8>,
50	    has_data: bool,
51	    event: Option<String>,
52	    skipping: bool,
53	}
54	
55	impl SseSplitter {
56	    pub(crate) fn new(max_record_bytes: usize) -> Self {
57	        SseSplitter {
58	            max_record_bytes,
59	            bom: BomState::Pending(Vec::with_capacity(BOM.len())),
60	            line: Vec::new(),
61	            line_bytes: 0,
62	            after_cr: false,
63	            record_bytes: 0,
64	            data: Vec::new(),
65	            has_data: false,
66	            event: None,
67	            skipping: false,
68	        }
69	    }
70	
71	    pub(crate) fn push(&mut self, chunk: &[u8]) -> Vec<SseItem> {
72	        let mut out = Vec::new();
73	        if let BomState::Pending(buf) = &mut self.bom {
74	            buf.extend_from_slice(chunk);
75	            if buf.len() < BOM.len() && BOM.starts_with(buf) {
76	                return out;
77	            }
78	            let mut head = std::mem::take(buf);
79	            self.bom = BomState::Done;
80	            if head.starts_with(BOM) {
81	                head.drain(..BOM.len());
82	            }
83	            for &b in &head {
84	                self.byte(b, &mut out);
85	            }
86	            return out;
87	        }
88	        for &b in chunk {
89	            self.byte(b, &mut out);
90	        }
91	        out
92	    }
93	
94	    /// The upstream ended: close the pending line, then dispatch the pending record (D4).
95	    pub(crate) fn finish(&mut self) -> Vec<SseItem> {
96	        let mut out = Vec::new();
97	        if let BomState::Pending(buf) = &mut self.bom {
98	            let head = std::mem::take(buf);
99	            self.bom = BomState::Done;
100	            for &b in &head {
101	                self.byte(b, &mut out);
102	            }
103	        }
104	        if self.line_bytes > 0 {
105	            self.end_line(&mut out);
106	        }
107	        self.after_cr = false;
108	        if self.skipping {
109	            self.skipping = false;
110	            self.reset_record();
111	        } else {
112	            self.dispatch(&mut out);
113	        }
114	        out
115	    }
116	
117	    fn byte(&mut self, b: u8, out: &mut Vec<SseItem>) {
118	        if self.after_cr {
119	            self.after_cr = false;
120	            if b == b'\n' {
121	                return;
122	            }
123	        }
124	        match b {
125	            b'\r' => {
126	                self.after_cr = true;
127	                self.end_line(out);
128	            }
129	            b'\n' => self.end_line(out),
130	            _ => {
131	                self.line_bytes += 1;
132	                self.record_bytes += 1;
133	                if self.skipping {
134	                    return;
135	                }
136	                if self.record_bytes > self.max_record_bytes {
137	                    self.skipping = true;
138	                    self.line.clear();
139	                    self.reset_record();
140	                    out.push(SseItem::Oversized);
141	                    return;
142	                }
143	                self.line.push(b);
144	            }
145	        }
146	    }
147	
148	    fn end_line(&mut self, out: &mut Vec<SseItem>) {
149	        let blank = self.line_bytes == 0;
150	        self.line_bytes = 0;
151	        let line = std::mem::take(&mut self.line);
152	        if blank {
153	            if self.skipping {
154	                self.skipping = false;
155	                self.reset_record();
156	            } else {
157	                self.dispatch(out);
158	            }
159	            return;
160	        }
161	        if !self.skipping {
162	            self.field(&line);
163	        }
164	    }
165	
166	    fn field(&mut self, line: &[u8]) {
167	        if line.first() == Some(&b':') {
168	            return; // a comment (dropped, D3)
169	        }
170	        let (name, value) = match line.iter().position(|&b| b == b':') {
171	            Some(i) => {
172	                let v = &line[i + 1..];
173	                (&line[..i], v.strip_prefix(b" ").unwrap_or(v))
174	            }
175	            None => (line, &b""[..]),
176	        };
177	        match name {
178	            b"data" => {
179	                self.data.extend_from_slice(value);
180	                self.data.push(b'\n');
181	                self.has_data = true;
182	            }
183	            b"event" => self.event = Some(String::from_utf8_lossy(value).into_owned()),
184	            _ => {} // `id`, `retry` and unknown fields are dropped (D3)
185	        }
186	    }
187	
188	    fn dispatch(&mut self, out: &mut Vec<SseItem>) {
189	        if self.has_data {
190	            let mut data = std::mem::take(&mut self.data);
191	            data.pop();
192	            if !data.is_empty() {
193	                out.push(SseItem::Record(Record { event: self.event.take(), data }));
194	            }
195	        }
196	        self.reset_record();
197	    }
198	
199	    fn reset_record(&mut self) {
200	        self.data.clear();
201	        self.has_data = false;
202	        self.event = None;
203	        self.record_bytes = 0;
204	    }
205	}
206	
207	/// Re-frame one record (D3): an optional `event:` line, one `data:` line per payload line, and the
208	/// blank line. The payload cannot hold a CR: the splitter ended a line at every CR.
209	pub(crate) fn frame(event: Option<&str>, payload: &[u8]) -> Bytes {
210	    let mut out = Vec::with_capacity(payload.len() + 24);
211	    if let Some(e) = event {
212	        out.extend_from_slice(b"event: ");
213	        out.extend_from_slice(e.as_bytes());
214	        out.push(b'\n');
215	    }
216	    for line in payload.split(|&b| b == b'\n') {
217	        out.extend_from_slice(b"data: ");
218	        out.extend_from_slice(line);
219	        out.push(b'\n');
220	    }
221	    out.push(b'\n');
222	    Bytes::from(out)
223	}
224	
225	/// One SSE comment. A CR or LF in `text` would end the comment early, so each becomes a space.
226	pub(crate) fn comment(text: &str) -> Bytes {
227	    let clean: String = text.chars().map(|c| if c == '\r' || c == '\n' { ' ' } else { c }).collect();
228	    Bytes::from(format!(": {clean}\n\n"))
229	}
230	
231	#[cfg(test)]
232	mod tests {
233	    use super::*;
234	
235	    fn records(items: Vec<SseItem>) -> Vec<(Option<String>, String)> {
236	        items
237	            .into_iter()
238	            .map(|i| match i {
239	                SseItem::Record(r) => (r.event, String::from_utf8(r.data).unwrap()),
240	                SseItem::Oversized => (None, "<oversized>".to_owned()),
241	            })
242	            .collect()
243	    }
244	
245	    fn split_all(input: &[u8], max: usize) -> Vec<(Option<String>, String)> {
246	        let mut s = SseSplitter::new(max);
247	        let mut out = s.push(input);
248	        out.extend(s.finish());
249	        records(out)
250	    }
251	
252	    #[test]
253	    fn all_three_line_endings_end_a_record() {
254	        for input in [&b"data: a\n\ndata: b\n\n"[..], b"data: a\r\n\r\ndata: b\r\n\r\n", b"data: a\r\rdata: b\r\r"] {
255	            assert_eq!(split_all(input, 1024), vec![(None, "a".into()), (None, "b".into())], "{input:?}");
256	        }
257	    }
258	
259	    #[test]
260	    fn every_split_point_gives_the_same_records() {
261	        let input = b"\xEF\xBB\xBFevent: e\r\ndata: {\"x\":1}\r\n\r\n: c\ndata: l1\ndata: l2\n\ndata: tail";
262	        let whole = split_all(input, 1024);
263	        assert_eq!(whole, vec![(Some("e".into()), "{\"x\":1}".into()), (None, "l1\nl2".into()), (None, "tail".into())]);
264	        for i in 0..=input.len() {
265	            for j in i..=input.len() {
266	                let mut s = SseSplitter::new(1024);
267	                let mut out = s.push(&input[..i]);
268	                out.extend(s.push(&input[i..j]));
269	                out.extend(s.push(&input[j..]));
270	                out.extend(s.finish());
271	                assert_eq!(records(out), whole, "split at {i},{j}");
272	            }
273	        }
274	    }
275	
276	    #[test]
277	    fn a_bom_is_stripped_once_and_only_at_the_start() {
278	        assert_eq!(split_all(b"\xEF\xBB\xBFdata: a\n\n", 64), vec![(None, "a".into())]);
279	        // A second BOM is part of the field name, so the line is an unknown field and is dropped.
280	        assert_eq!(split_all(b"\xEF\xBB\xBF\xEF\xBB\xBFdata: a\n\n", 64), vec![]);
281	        // A BOM-like prefix that is not a BOM is kept.
282	        assert_eq!(split_all(b"\xEF\xBBdata: a\n\n", 64), vec![]);
283	    }
284	
285	    #[test]
286	    fn comments_ids_retries_and_unknown_fields_are_dropped() {
287	        assert_eq!(split_all(b": hi\nid: 7\nretry: 10\nfoo: bar\ndata: a\n\n", 64), vec![(None, "a".into())]);
288	    }
289	
290	    #[test]
291	    fn a_lax_line_is_an_unknown_field_not_data() {
292	        // `  data: x` and `Data: x` are what a trimming or case-blind client would read as data.
293	        assert_eq!(split_all(b"  data: x\n\nData: y\n\n", 64), vec![]);
294	    }
295	
296	    #[test]
297	    fn data_without_a_space_and_with_two_spaces() {
298	        assert_eq!(split_all(b"data:a\n\ndata:  b\n\n", 64), vec![(None, "a".into()), (None, " b".into())]);
299	    }
300	
301	    #[test]
302	    fn an_empty_data_buffer_dispatches_nothing() {
303	        assert_eq!(split_all(b"data:\n\nevent: x\n\n", 64), vec![]);
304	    }
305	
306	    #[test]
307	    fn the_unterminated_tail_is_dispatched_by_finish() {
308	        let mut s = SseSplitter::new(64);
309	        assert!(s.push(b"data: a").is_empty());
310	        assert_eq!(records(s.finish()), vec![(None, "a".into())]);
311	    }
312	
313	    #[test]
314	    fn an_oversized_record_is_reported_once_and_the_next_record_survives() {
315	        let mut input = b"data: ".to_vec();
316	        input.extend(std::iter::repeat_n(b'x', 100));
317	        input.extend_from_slice(b"\ndata: more\n\ndata: ok\n\n");
318	        assert_eq!(split_all(&input, 32), vec![(None, "<oversized>".into()), (None, "ok".into())]);
319	    }
320	
321	    #[test]
322	    fn frame_writes_one_data_line_per_payload_line() {
323	        assert_eq!(&frame(None, b"{}")[..], b"data: {}\n\n");
324	        assert_eq!(&frame(Some("ping"), b"a\nb")[..], b"event: ping\ndata: a\ndata: b\n\n");
325	    }
326	
327	    #[test]
328	    fn comment_never_breaks_the_frame() {
329	        assert_eq!(&comment("x")[..], b": x\n\n");
330	        assert_eq!(&comment("a\r\nb")[..], b": a  b\n\n");
331	        assert_eq!(KEEP_ALIVE, b": keep-alive\n\n");
332	    }
333	}
