343	    /// SMA-730 U3: after a blank line `finish()` changes nothing, and a second call changes nothing.
344	    #[test]
345	    fn finish_is_a_no_op_after_a_blank_line_and_when_called_twice() {
346	        let stream = format!("{}{}", chunk("a", true), usage_chunk(7));
347	        let mut scanner = finished(&[stream.as_str()]);
348	        assert_eq!((scanner.completion_records(), scanner.reported_total()), (1, Some(7)));
349	        scanner.finish();
350	        assert_eq!((scanner.completion_records(), scanner.reported_total()), (1, Some(7)));
351	        let mut once = finished(&["data: a"]);
352	        once.finish();
353	        assert_eq!(once.completion_records(), 1, "a second finish does not count the record again");
354	    }
355	
356	    /// Review Focus 1: an unterminated `[DONE]` after the usage record keeps the usage.
357	    #[test]
358	    fn finish_after_an_unterminated_done_keeps_the_usage() {
359	        let stream = format!("{}data: [DONE]", usage_chunk(7));
360	        let scanner = finished(&[stream.as_str()]);
361	        assert_eq!((scanner.completion_records(), scanner.reported_total()), (0, Some(7)));
362	    }
363	
364	    /// SMA-730 U4: an oversized partial record at the end counts once.
365	    #[test]
366	    fn finish_counts_an_oversized_partial_record_once() {
367	        let mut scanner = UsageScanner::new();
368	        scanner.feed(b"data: ");
369	        scanner.feed(&vec![b'x'; MAX_RECORD_BYTES + 1]);
370	        scanner.finish();
371	        assert_eq!(scanner.completion_records(), 1);
372	    }
373	
374	    /// Review Focus 4 and D14.
375	    #[test]
376	    fn request_estimate_shapes() {
377	        let est = |messages: serde_json::Value, body_len: usize| request_tokens_estimate(messages.as_array().expect("an array"), body_len);
378	        // String contents: 5 + 2 bytes → ceil(7 / 4) = 2.
379	        assert_eq!(est(json!([{"role": "system", "content": "hello"}, {"role": "user", "content": "hi"}]), 999), 2);
380	        // A text part and an image part: ceil(4 / 4) + 85.
381	        assert_eq!(
382	            est(
383	                json!([{"role": "user", "content": [{"type": "text", "text": "abcd"}, {"type": "image_url", "image_url": {"url": "data:image/png;base64,AAAA"}}]}]),
384	                999
385	            ),
386	            86
387	        );
388	        // `content: null` with tool calls counts 0, and is not a reason for the fallback.
389	        assert_eq!(
390	            est(json!([{"role": "assistant", "content": null, "tool_calls": [{"id": "c1"}]}, {"role": "user", "content": "abcd"}]), 999),
391	            1
392	        );
393	        // An unknown shape uses ceil(body_len / 4), capped at 32768.
394	        assert_eq!(est(json!([{"role": "user", "content": 42}]), 400), 100);
395	        assert_eq!(est(json!(["not an object"]), 400), 100);
396	        assert_eq!(est(json!([{"role": "user", "content": [{"text": "no type"}]}]), 401), 101);
397	        assert_eq!(est(json!([{"role": "user", "content": 42}]), 1_000_000), 32_768);
398	        assert_eq!(est(json!([]), 10), 0);
399	    }
400	
401	    #[test]
402	    fn non_stream_usage_reads_usage_or_estimates_the_completion() {
403	        assert_eq!(non_stream_usage(br#"{"choices":[],"usage":{"total_tokens":12}}"#), BodyUsage::Reported(12));
404	        // 8 content bytes + 7 argument bytes (`{"a":1}`) → ceil(15 / 4) = 4.
405	        let body = br#"{"choices":[{"message":{"content":"abcdefgh","tool_calls":[{"function":{"name":"f","arguments":"{\"a\":1}"}}]}}]}"#;
406	        assert_eq!(non_stream_usage(body), BodyUsage::Completion(4));
407	        assert_eq!(non_stream_usage(b"not json"), BodyUsage::Completion(0));
408	        assert_eq!(non_stream_usage(br#"{"usage":{"total_tokens":"many"},"choices":[]}"#), BodyUsage::Completion(0));
409	    }
