1	// SPDX-License-Identifier: Apache-2.0
2	
3	//! The inbound chat-completion request DTO.
4	//!
5	//! G7 parses the caller's JSON body into [`ChatCompletionRequest`] for exactly two reasons: to
6	//! read `model` (request logging) and `stream` (choosing the streaming vs non-streaming egress
7	//! path). It is **not** the wire body sent upstream — the OpenAI client forwards the caller's
8	//! ORIGINAL raw bytes verbatim (see [`crate::adapters::openai`]), so passthrough is byte-lossless
9	//! regardless of anything this DTO does or does not model.
10	//!
11	//! `#[serde(flatten)] extra` therefore exists as a belt-and-braces guarantee: every field this
12	//! struct does not name is preserved rather than dropped, so a re-serialization would still be
13	//! lossless (a secondary safety net, not the primary passthrough mechanism).
14	
15	use serde::{Deserialize, Serialize};
16	
17	/// An OpenAI-compatible `POST /v1/chat/completions` request body, modelled just enough for the
18	/// gateway's needs. `model` and `messages` are the required core; `stream` selects the egress
19	/// path (defaults to `false` when absent); every other top-level field (`temperature`, `top_p`,
20	/// `tools`, `response_format`, …) is captured losslessly in [`extra`](Self::extra).
21	#[derive(Debug, Clone, Deserialize, Serialize)]
22	pub struct ChatCompletionRequest {
23	    /// The target model id (read for request logging; the upstream body carries it verbatim).
24	    pub model: String,
25	    /// Whether the caller requested a streamed (SSE) completion. Absent → `false`.
26	    #[serde(default)]
27	    pub stream: bool,
28	    /// The conversation turns, kept as opaque JSON. The gateway reads only the lengths of the
29	    /// message text, to estimate tokens. It never logs the content and never changes it.
30	    pub messages: Vec<serde_json::Value>,
31	    /// Every unmodelled top-level field, preserved verbatim so a round-trip is lossless.
32	    #[serde(flatten)]
33	    pub extra: serde_json::Map<String, serde_json::Value>,
34	}
35	
36	#[cfg(test)]
37	mod tests {
38	    use super::*;
39	    use serde_json::json;
40	
41	    #[test]
42	    fn parses_core_fields_and_captures_unknowns_in_extra() {
43	        // A realistic request carrying `model`/`stream`/`messages` plus several unmodelled
44	        // top-level fields — the exact shape a caller's OpenAI SDK emits.
45	        let raw = json!({
46	            "model": "gpt-4o-mini",
47	            "stream": true,
48	            "messages": [{ "role": "user", "content": "hi" }],
49	            "temperature": 0.7,
50	            "top_p": 0.9,
51	            "tools": [{ "type": "function", "function": { "name": "f" } }],
52	            "response_format": { "type": "json_object" }
53	        });
54	
55	        let req: ChatCompletionRequest = serde_json::from_value(raw).expect("valid request parses");
56	
57	        assert_eq!(req.model, "gpt-4o-mini");
58	        assert!(req.stream);
59	        assert_eq!(req.messages.len(), 1);
60	
61	        // Every unknown top-level field landed in `extra` — and NOTHING that was named leaked
62	        // into it.
63	        assert_eq!(req.extra.get("temperature"), Some(&json!(0.7)));
64	        assert_eq!(req.extra.get("top_p"), Some(&json!(0.9)));
65	        assert_eq!(req.extra.get("tools"), Some(&json!([{ "type": "function", "function": { "name": "f" } }])));
66	        assert_eq!(req.extra.get("response_format"), Some(&json!({ "type": "json_object" })));
67	        assert!(!req.extra.contains_key("model"), "named fields must not bleed into `extra`");
68	        assert!(!req.extra.contains_key("stream"));
69	        assert!(!req.extra.contains_key("messages"));
70	    }
71	
72	    #[test]
73	    fn round_trip_preserves_the_extra_fields_losslessly() {
74	        let raw = json!({
75	            "model": "gpt-4o",
76	            "messages": [{ "role": "system", "content": "be terse" }],
77	            "temperature": 0.2,
78	            "seed": 42,
79	            "metadata": { "team": "a", "nested": { "k": "v" } }
80	        });
81	
82	        let req: ChatCompletionRequest = serde_json::from_value(raw.clone()).expect("valid request parses");
83	        let reserialized = serde_json::to_value(&req).expect("re-serializes");
84	
85	        // The extra fields survive the round-trip byte-for-value (order-independent JSON equality).
86	        assert_eq!(reserialized.get("temperature"), Some(&json!(0.2)));
87	        assert_eq!(reserialized.get("seed"), Some(&json!(42)));
88	        assert_eq!(reserialized.get("metadata"), Some(&json!({ "team": "a", "nested": { "k": "v" } })));
89	        // Core fields survive too, at the top level (flatten does not nest them).
90	        assert_eq!(reserialized.get("model"), Some(&json!("gpt-4o")));
91	        assert_eq!(reserialized.get("messages"), raw.get("messages"));
92	    }
93	
94	    #[test]
95	    fn stream_defaults_to_false_when_absent() {
96	        let raw = json!({
97	            "model": "gpt-4o",
98	            "messages": []
99	        });
100	        let req: ChatCompletionRequest = serde_json::from_value(raw).expect("valid request parses");
101	        assert!(!req.stream, "`stream` must default to false when the field is absent");
102	    }
