1	// SPDX-License-Identifier: Apache-2.0
2	//! SMA-749: drives `paigasus-gateway-core` inside the chat relay (spec § 5.2).
3	//!
4	//! The interceptor is synchronous; this module owns the I/O around it: the upstream stream, one
5	//! pending decider future, and one timer. Nothing is spawned. Dropping the response body drops
6	//! the unfold state, and with it the upstream request (cancel-on-drop, D25) and any pending
7	//! decision.
8	//!
9	//! Like the plain relay, this runs with `current_ids() == None` (SMA-504 § 4.3): the request id
10	//! reaches the decider through `DecisionContext`, captured in the handler.
11	//!
12	//! The decider future and the timer are driven only while the client polls the body, so a client
13	//! that stalls long enough can see a hold end as `decider-error` (or `on_failure` in observe mode).
14	//!
15	//! On a client disconnect mid-hold, billing follows what the relay had read from the upstream so
16	//! far, read-ahead included, exactly as in the plain relay (SMA-730 D3).
17	
18	use std::collections::VecDeque;
19	use std::convert::Infallible;
20	use std::pin::Pin;
21	use std::sync::Arc;
22	use std::time::Instant;
23	
24	use axum::body::Bytes;
25	use futures::{Stream, StreamExt};
26	use metrics::{counter, histogram};
27	use paigasus_gateway_core::{
28	    Action, Basis, BlockCode, DecideFuture, DeciderError, Decision, DecisionContext, Format, HoldKey, Interceptor, Limits, Metric, OnFailure, ToolCall, ToolCallDecider, ToolTurn, parse_body,
29	};
30	use paigasus_observability::names;
31	
32	use crate::adapters::http::chat::{feed_scan, finish_scan};
33	use crate::adapters::http::usage::UsageScanner;
34	use crate::adapters::openai::OpenAiByteStream;
35	use crate::application::charge_guard::ChargeGuard;
36	
37	/// What `[tool_interception]` builds at boot.
38	pub struct ToolInterception {
39	    pub limits: Limits,
40	    pub decider: Arc<dyn ToolCallDecider>,
41	}
42	
43	/// Map one core metric to the registered names (P-9).
44	pub(crate) fn record(m: Metric) {
45	    match m {
46	        Metric::RecordDropped(reason) => counter!(names::GATEWAY_TOOL_INTERCEPTION_RECORDS_DROPPED_TOTAL, "reason" => reason).increment(1),
47	        Metric::Decision { decision, basis } => counter!(names::GATEWAY_TOOL_INTERCEPTION_DECISIONS_TOTAL, "decision" => decision, "basis" => basis).increment(1),
48	        Metric::OnFailure(code) => counter!(names::GATEWAY_TOOL_INTERCEPTION_ON_FAILURE_TOTAL, "code" => code).increment(1),
49	        Metric::HoldSeconds(s) => histogram!(names::GATEWAY_TOOL_INTERCEPTION_HOLD_SECONDS).record(s),
50	    }
51	}
52	
53	/// What the non-stream path does with a body (spec § 5.2).
54	pub(crate) enum BodyOutcome {
55	    /// `rewritten` is `None` when the caller forwards the original body it still owns.
56	    Forward { rewritten: Option<Bytes>, report: Option<String> },
57	    /// D16 block on a body that cannot be checked: the 502 `tool-interception-malformed-response`.
58	    Refuse,
59	}
60	
61	/// Parse, decide and rewrite one complete 2xx body. The usage read happened on the ORIGINAL body
62	/// before this runs (D24), so nothing here changes the charge.
63	pub(crate) async fn intercept_body(ti: &ToolInterception, ctx: Arc<DecisionContext>, turn: Arc<ToolTurn>, body: &[u8]) -> BodyOutcome {
64	    // The body cap is `max_held_bytes` (spec § 5.2).
65	    let calls = match parse_body(Format::OpenAiChat, body, ti.limits.max_held_bytes) {
66	        Ok(c) => c,
67	        Err(_) => {
68	            record(Metric::OnFailure("malformed"));
69	            return match ti.limits.on_failure {
70	                OnFailure::Block => BodyOutcome::Refuse,
71	                OnFailure::Allow => BodyOutcome::Forward { rewritten: None, report: None },
72	            };
73	        }
74	    };
75	    if calls.calls.is_empty() && calls.unenforceable.is_empty() {
76	        return BodyOutcome::Forward { rewritten: None, report: None };
77	    }
78	    let n = calls.calls.len();
79	    let (decisions, basis) = if n == 0 {
80	        (Vec::new(), Basis::Decider)
81	    } else {
82	        let fut = ti.decider.decide(ctx, turn, calls.calls.clone());
83	        match tokio::time::timeout(ti.limits.decide_timeout, fut).await {
84	            Ok(Ok(d)) if d.len() == n => (d, Basis::Decider),
85	            _ => {
86	                record(Metric::OnFailure("decider_error"));
87	                match ti.limits.on_failure {
88	                    OnFailure::Block => (vec![Decision::Block { code: BlockCode::DeciderError }; n], Basis::OnFailure),
89	                    OnFailure::Allow => (vec![Decision::Allow; n], Basis::OnFailure),
90	                }
91	            }
92	        }
93	    };
94	    for d in &decisions {
95	        let decision = if d.is_allow() { "allow" } else { "block" };
96	        record(Metric::Decision { decision, basis: basis.as_str() });
97	    }
98	    let report = calls.report(&decisions, basis);
99	    let rewritten = calls.apply(&decisions).map(Bytes::from);
100	    BodyOutcome::Forward { rewritten, report: Some(report) }
101	}
102	
103	/// The unfold state. It owns the upstream, the charge guard and the pending decision, so a
104	/// client disconnect drops all three (D25), exactly as the plain relay drops the first two.
105	struct Relay {
106	    /// `None` once the upstream has ended, failed, or been drained.
107	    inner: Option<OpenAiByteStream>,
108	    scan: UsageScanner,
109	    guard: Option<ChargeGuard>,
110	    icpt: Interceptor,
111	    ti: Arc<ToolInterception>,
112	    ctx: Arc<DecisionContext>,
113	    turn: Arc<ToolTurn>,
114	    out: VecDeque<Bytes>,
115	    /// Completed holds waiting for the decider, in completion order (P-5).
116	    decide_queue: VecDeque<(HoldKey, Vec<ToolCall>)>,
117	    /// The one decision in flight (P-5).
118	    pending: Option<(HoldKey, DecideFuture)>,
119	    sleep: Pin<Box<tokio::time::Sleep>>,
120	}
121	
122	/// What woke the relay.
123	enum Event {
124	    Decided(Result<Vec<Decision>, DeciderError>),
125	    Wake,
126	    Upstream(Option<Result<Bytes, reqwest::Error>>),
127	}
128	
129	impl Relay {
130	    fn apply(&mut self, actions: Vec<Action>) {
131	        for a in actions {
132	            match a {
133	                Action::Emit(b) => self.out.push_back(b),
134	                Action::Decide { hold, calls } => self.decide_queue.push_back((hold, calls)),
135	                // The core never returns a wake in the past, so this cannot spin.
136	                Action::Wake(at) => self.sleep.as_mut().reset(tokio::time::Instant::from_std(at)),
137	                Action::Count(m) => record(m),
138	            }
139	        }
140	        // A hold that is no longer deciding (a timeout ruled on it) needs no answer. Drop
141	        // its future so the next hold is not stuck behind it.
142	        if let Some((hold, _)) = &self.pending
143	            && !self.icpt.is_deciding(*hold)
144	        {
145	            self.pending = None;
146	        }
147	    }
148	
149	    /// Start the next decision if none is in flight. Holds ruled on while they queued are skipped.
150	    fn start_next_decision(&mut self) {
151	        while self.pending.is_none() {
152	            let Some((hold, calls)) = self.decide_queue.pop_front() else { return };
153	            if self.icpt.is_deciding(hold) {
154	                let fut = self.ti.decider.decide(Arc::clone(&self.ctx), Arc::clone(&self.turn), calls);
155	                self.pending = Some((hold, fut));
156	            }
157	        }
158	    }
159	
160	    /// Biased in the spec's order (§ 5.2): decider, timer, upstream.
161	    async fn next_event(&mut self) -> Event {
162	        let Relay { inner, pending, sleep, .. } = self;
163	        tokio::select! {
164	            biased;
165	            r = async {
166	                match pending.as_mut() {
167	                    Some((_, f)) => f.as_mut().await,
168	                    None => std::future::pending().await,
169	                }
170	            } => Event::Decided(r),
171	            () = sleep.as_mut() => Event::Wake,
172	            c = async {
173	                match inner.as_mut() {
174	                    Some(s) => s.next().await,
175	                    None => std::future::pending().await,
176	                }
177	            } => Event::Upstream(c),
178	        }
179	    }
180	
181	    /// The interceptor ended the client stream (an upstream error record mid-hold) while the
182	    /// upstream is still open. Today's relay would read the upstream to its end, so with a guard
183	    /// the rest is read for billing only (the usage record usually follows), and the charge stays
184	    /// what it is with interception off (D24). Without a guard there is nothing to bill, and the
185	    /// upstream is dropped at once.
186	    async fn drain_for_billing(&mut self) {
187	        let Some(mut inner) = self.inner.take() else { return };
188	        if self.guard.is_some() {
189	            while let Some(Ok(chunk)) = inner.next().await {
190	                feed_scan(&mut self.scan, &mut self.guard, &chunk);
191	            }
192	        }
193	        finish_scan(&mut self.scan, &mut self.guard);
194	    }
195	}
196	
197	/// The streaming relay with interception on (spec § 5.2, D17, D24, D25).
198	///
199	/// 1. Each upstream chunk goes to the usage scanner first, exactly as in the plain relay, and
200	///    then to [`Interceptor::push`].
201	/// 2. On the first upstream `Err`: `finish_scan`, then [`Interceptor::abort`], which emits the
202	///    terminal frame. The relay does not emit it a second time.
203	/// 3. On the upstream end: `finish_scan`, then [`Interceptor::finish`].
204	/// 4. Decisions run one at a time (P-5).
205	/// 5. Nothing is spawned.
206	pub(crate) fn intercepted_stream(
207	    inner: OpenAiByteStream,
208	    guard: Option<ChargeGuard>,
209	    ti: Arc<ToolInterception>,
210	    ctx: Arc<DecisionContext>,
211	    turn: Arc<ToolTurn>,
212	    terminal: &'static [u8],
213	) -> impl Stream<Item = Result<Bytes, Infallible>> + Send + 'static {
214	    relay(Format::OpenAiChat, inner, guard, ti, ctx, turn, terminal)
215	}
216	
217	/// [`intercepted_stream`] for any wire format. Only OpenAI chat is wired in SMA-749 (D26); the
218	/// unit tests drive an Anthropic stream through it, because only that format has more than one
219	/// hold per stream (an OpenAI stream carries tool calls in choice 0 only), and P-5 and the
220	/// dropped stale decision are about the second hold.
221	fn relay(
222	    format: Format,
223	    inner: OpenAiByteStream,
224	    guard: Option<ChargeGuard>,
225	    ti: Arc<ToolInterception>,
226	    ctx: Arc<DecisionContext>,
227	    turn: Arc<ToolTurn>,
228	    terminal: &'static [u8],
229	) -> impl Stream<Item = Result<Bytes, Infallible>> + Send + 'static {
230	    let now = Instant::now();
231	    let icpt = Interceptor::new(format, ti.limits, Bytes::from_static(terminal), now);
232	    let sleep = Box::pin(tokio::time::sleep(ti.limits.keepalive));
233	    let start = Relay {
234	        inner: Some(inner),
235	        scan: UsageScanner::new(),
236	        guard,
237	        icpt,
238	        ti,
239	        ctx,
240	        turn,
241	        out: VecDeque::new(),
242	        decide_queue: VecDeque::new(),
243	        pending: None,
244	        sleep,
245	    };
246	    futures::stream::unfold(start, |mut st| async move {
247	        loop {
248	            if let Some(b) = st.out.pop_front() {
249	                return Some((Ok(b), st));
250	            }
251	            // Checked before `select!`, so an elapsed timer after the end cannot spin.
252	            if st.icpt.is_finished() {
253	                st.drain_for_billing().await;
254	                return None;
255	            }
256	            st.start_next_decision();
257	            let acts = match st.next_event().await {
258	                Event::Decided(r) => {
259	                    let (hold, _) = st.pending.take().expect("the resolved decision was pending");
260	                    st.icpt.decided(hold, r, Instant::now())
261	                }
262	                Event::Wake => st.icpt.tick(Instant::now()),
263	                Event::Upstream(Some(Ok(chunk))) => {
264	                    feed_scan(&mut st.scan, &mut st.guard, &chunk);
265	                    st.icpt.push(&chunk, Instant::now())
266	                }
267	                Event::Upstream(Some(Err(_))) => {
268	                    finish_scan(&mut st.scan, &mut st.guard);
269	                    st.inner = None;
270	                    st.icpt.abort()
271	                }
272	                Event::Upstream(None) => {
273	                    finish_scan(&mut st.scan, &mut st.guard);
274	                    st.inner = None;
275	                    st.icpt.finish(Instant::now())
276	                }
277	            };
278	            st.apply(acts);
279	        }
280	    })
281	}
282	
283	#[cfg(test)]
284	mod tests {
285	    use std::sync::atomic::{AtomicUsize, Ordering};
286	    use std::time::Duration;
287	
288	    use metrics_util::debugging::{DebugValue, DebuggingRecorder};
289	
290	    use super::*;
291	
292	    /// A metric name, its labels and its value.
293	    type Sample = (String, Vec<(String, String)>, DebugValue);
294	
295	    /// P-9: every core metric lands on its registered name with its closed label set. One
296	    /// snapshot: the debugging recorder drains counters when it is read.
297	    #[test]
298	    fn core_metrics_map_to_the_registered_names() {
299	        let recorder = DebuggingRecorder::new();
300	        let snapshotter = recorder.snapshotter();
301	        let _local = metrics::set_default_local_recorder(&recorder);
302	        record(Metric::RecordDropped("malformed"));
303	        record(Metric::Decision { decision: "block", basis: "decider" });
304	        record(Metric::OnFailure("hold_limit"));
305	        record(Metric::HoldSeconds(0.25));
306	        let mut seen: Vec<Sample> = snapshotter
307	            .snapshot()
308	            .into_vec()
309	            .into_iter()
310	            .map(|(k, _, _, v)| (k.key().name().to_owned(), k.key().labels().map(|l| (l.key().to_owned(), l.value().to_owned())).collect(), v))
311	            .collect();
312	        seen.sort_by(|a, b| a.0.cmp(&b.0));
313	        let labels = |pairs: &[(&str, &str)]| pairs.iter().map(|(k, v)| ((*k).to_owned(), (*v).to_owned())).collect::<Vec<_>>();
314	        assert_eq!(
315	            seen,
316	            vec![
317	                (
318	                    names::GATEWAY_TOOL_INTERCEPTION_DECISIONS_TOTAL.to_owned(),
319	                    labels(&[("decision", "block"), ("basis", "decider")]),
320	                    DebugValue::Counter(1)
321	                ),
322	                (names::GATEWAY_TOOL_INTERCEPTION_HOLD_SECONDS.to_owned(), labels(&[]), DebugValue::Histogram(vec![0.25.into()])),
323	                (names::GATEWAY_TOOL_INTERCEPTION_ON_FAILURE_TOTAL.to_owned(), labels(&[("code", "hold_limit")]), DebugValue::Counter(1)),
324	                (
325	                    names::GATEWAY_TOOL_INTERCEPTION_RECORDS_DROPPED_TOTAL.to_owned(),
326	                    labels(&[("reason", "malformed")]),
327	                    DebugValue::Counter(1)
328	                ),
329	            ]
330	        );
331	    }
332	
333	    const TERMINAL: &[u8] = b"\n\ndata: {\"error\":\"terminal\"}\n\n";
334	
335	    /// Two complete `tool_use` blocks: two holds, `Block(0)` and `Block(1)`, completed in order,
336	    /// with `gap` between the first block's end and the second block's start.
337	    fn two_tool_blocks(first: &str, second: &str, gap: Duration) -> OpenAiByteStream {
338	        let ev = |name: &str, data: String| Ok(Bytes::from(format!("event: {name}\ndata: {data}\n\n")));
339	        let block = |i: u32, name: &str| {
340	            vec![
341	                ev(
342	                    "content_block_start",
343	                    format!(r#"{{"type":"content_block_start","index":{i},"content_block":{{"type":"tool_use","id":"toolu_{i}","name":"{name}","input":{{}}}}}}"#),
344	                ),
345	                ev(
346	                    "content_block_delta",
347	                    format!(r#"{{"type":"content_block_delta","index":{i},"delta":{{"type":"input_json_delta","partial_json":"{{\"p\":{i}}}"}}}}"#),
348	                ),
349	                ev("content_block_stop", format!(r#"{{"type":"content_block_stop","index":{i}}}"#)),
350	            ]
351	        };
352	        let mut chunks = vec![ev(
353	            "message_start",
354	            r#"{"type":"message_start","message":{"id":"msg_1","type":"message","role":"assistant","content":[],"model":"claude-x","stop_reason":null}}"#.to_owned(),
355	        )];
356	        chunks.extend(block(0, first));
357	        let second_starts = chunks.len();
358	        chunks.extend(block(1, second));
359	        chunks.push(ev(
360	            "message_delta",
361	            r#"{"type":"message_delta","delta":{"stop_reason":"tool_use","stop_sequence":null},"usage":{"output_tokens":7}}"#.to_owned(),
362	        ));
363	        chunks.push(ev("message_stop", r#"{"type":"message_stop"}"#.to_owned()));
364	        futures::stream::iter(chunks.into_iter().enumerate())
365	            .then(move |(i, c)| async move {
366	                if i == second_starts {
367	                    tokio::time::sleep(gap).await;
368	                }
369	                c
370	            })
371	            .boxed()
372	    }
373	
374	    async fn run(decider: Arc<dyn ToolCallDecider>, limits: Limits, upstream: OpenAiByteStream) -> String {
375	        let ti = Arc::new(ToolInterception { limits, decider });
376	        let ctx = Arc::new(DecisionContext::new("principal", "scope", None));
377	        let turn = Arc::new(ToolTurn::Unavailable("unit test"));
378	        let out: Vec<Bytes> = relay(Format::AnthropicMessages, upstream, None, ti, ctx, turn, TERMINAL)
379	            .map(|r| r.expect("infallible"))
380	            .collect()
381	            .await;
382	        String::from_utf8(out.concat()).expect("utf-8")
383	    }
384	
385	    /// Allows everything after a short wait, and records the most decisions ever in flight.
386	    #[derive(Default)]
387	    struct SlowCounting {
388	        in_flight: Arc<AtomicUsize>,
389	        max_in_flight: Arc<AtomicUsize>,
390	        calls: Arc<AtomicUsize>,
391	    }
392	
393	    impl ToolCallDecider for SlowCounting {
394	        fn decide(&self, _ctx: Arc<DecisionContext>, _turn: Arc<ToolTurn>, calls: Vec<ToolCall>) -> DecideFuture {
395	            let (in_flight, max, count) = (Arc::clone(&self.in_flight), Arc::clone(&self.max_in_flight), Arc::clone(&self.calls));
396	            Box::pin(async move {
397	                let now = in_flight.fetch_add(1, Ordering::SeqCst) + 1;
398	                max.fetch_max(now, Ordering::SeqCst);
399	                count.fetch_add(1, Ordering::SeqCst);
400	                tokio::time::sleep(Duration::from_millis(30)).await;
401	                in_flight.fetch_sub(1, Ordering::SeqCst);
402	                Ok(vec![Decision::Allow; calls.len()])
403	            })
404	        }
405	    }
406	
407	    /// Never answers for a call named `hang_*`; allows everything else at once.
408	    struct HangNamed;
409	
410	    impl ToolCallDecider for HangNamed {
411	        fn decide(&self, _ctx: Arc<DecisionContext>, _turn: Arc<ToolTurn>, calls: Vec<ToolCall>) -> DecideFuture {
412	            if calls.iter().any(|c| c.name.starts_with("hang_")) {
413	                return Box::pin(std::future::pending());
414	            }
415	            Box::pin(std::future::ready(Ok(vec![Decision::Allow; calls.len()])))
416	        }
417	    }
418	
419	    /// SMA-730 R1 with interception on: a transport error after an unterminated usage record runs
420	    /// `finish_scan` before `abort()`, so the reported total is charged, and the core's terminal
421	    /// frame is the only one.
422	    #[tokio::test]
423	    async fn a_transport_error_after_an_unterminated_usage_record_charges_the_reported_tokens() {
424	        use crate::adapters::http::chat::TERMINAL_SSE_ERROR;
425	        use crate::adapters::http::chat::tests::{UNTERMINATED_USAGE, admit, make_reqwest_error, sent_guard};
426	        use crate::test_support::ScriptedStore;
427	        let store = ScriptedStore::new(admit);
428	        let upstream = futures::stream::iter(vec![Ok(Bytes::from_static(UNTERMINATED_USAGE))])
429	            .chain(futures::stream::once(async { Err(make_reqwest_error().await) }))
430	            .boxed();
431	        let ti = Arc::new(ToolInterception {
432	            limits: Limits::defaults(),
433	            decider: Arc::new(paigasus_gateway_core::AllowAll),
434	        });
435	        let ctx = Arc::new(DecisionContext::new("principal", "scope", None));
436	        let turn = Arc::new(ToolTurn::Unavailable("unit test"));
437	        let out: Vec<Bytes> = intercepted_stream(upstream, Some(sent_guard(&store)), ti, ctx, turn, TERMINAL_SSE_ERROR.as_bytes())
438	            .map(|r| r.expect("infallible"))
439	            .collect()
440	            .await;
441	        let text = String::from_utf8(out.concat()).expect("utf-8");
442	        assert_eq!(text.matches(TERMINAL_SSE_ERROR.trim()).count(), 1, "{text}");
443	        assert_eq!(store.charges(), vec![7]);
444	    }
445	
446	    /// P-5: two holds, decided one after the other, never both at once.
447	    #[tokio::test]
448	    async fn the_decider_runs_one_hold_at_a_time() {
449	        let decider = Arc::new(SlowCounting::default());
450	        let text = run(decider.clone(), Limits::defaults(), two_tool_blocks("read_file", "list_dir", Duration::ZERO)).await;
451	        assert!(text.contains(r#""decision":"allow","basis":"decider""#), "{text}");
452	        assert_eq!(decider.calls.load(Ordering::SeqCst), 2);
453	        assert_eq!(decider.max_in_flight.load(Ordering::SeqCst), 1);
454	    }
455	
456	    /// When a timeout rules on the hold being decided, its future is dropped and the next
457	    /// hold is decided. The second hold completes 600 ms after the first, so its own deadline
458	    /// (1.6 s) lies 600 ms after the first one's (1 s): kept, the stale future would hold it until
459	    /// that deadline and it would be blocked too. Wide margins, for a loaded CI runner.
460	    #[tokio::test]
461	    async fn a_timed_out_decision_does_not_block_the_next_hold() {
462	        let limits = Limits {
463	            decide_timeout: Duration::from_secs(1),
464	            ..Limits::defaults()
465	        };
466	        let text = tokio::time::timeout(
467	            Duration::from_secs(5),
468	            run(Arc::new(HangNamed), limits, two_tool_blocks("hang_x", "read_file", Duration::from_millis(600))),
469	        )
470	        .await
471	        .expect("the stream ends");
472	        assert!(
473	            text.contains(r#""name":"hang_x","name_sha256_8""#) && text.contains(&format!(r#""code":"{}""#, BlockCode::DeciderError.as_kebab())),
474	            "{text}"
475	        );
476	        assert!(text.contains(r#""name":"read_file","name_sha256_8""#), "{text}");
477	        let read_file_report = text
478	            .lines()
479	            .find(|l| l.contains(r#""name":"read_file""#) && l.starts_with(": paigasus-decision"))
480	            .expect("a report for read_file");
481	        assert!(read_file_report.contains(r#""decision":"allow","basis":"decider""#), "{read_file_report}");
482	        assert!(text.contains(r#""name":"read_file","input":{}"#), "the allowed call is forwarded: {text}");
483	    }
484	}
