3	//! The OpenAI wire readers for the charge (SMA-677 D14, § 4.6): the request estimate, the
4	//! non-stream completion estimate, and `UsageScanner`, which reads a COPY of a forwarded SSE
5	//! stream. None of them changes a byte that reaches the client (A5).
6	
7	use serde_json::Value;
8	
9	/// § 4.6: the bound on one partial SSE record. A larger record is skipped, not buffered, and
10	/// still counts as one record. The same bound as the console parser (`chat-stream.ts`).
11	pub const MAX_RECORD_BYTES: usize = 64 * 1024;
12	/// D14: the fallback request estimate is capped.
13	const FALLBACK_REQUEST_CAP: u64 = 32_768;
14	/// D14: an image, audio or other non-text part counts OpenAI's low-detail image cost.
15	const NON_TEXT_PART_TOKENS: u64 = 85;
16	
17	fn bytes_to_tokens(bytes: usize) -> u64 {
18	    u64::try_from(bytes).unwrap_or(u64::MAX).div_ceil(4)
19	}
20	
21	/// D14: `ceil(text_bytes / 4)` over every string `content` and every `text` part, plus 85 per
22	/// non-text part. A `null` or absent `content` counts 0. Any other shape falls back to
23	/// `ceil(body_len / 4)`, capped at 32768.
24	pub fn request_tokens_estimate(messages: &[Value], body_len: usize) -> u64 {
25	    let fallback = bytes_to_tokens(body_len).min(FALLBACK_REQUEST_CAP);
26	    let mut text_bytes = 0usize;
27	    let mut other_parts = 0u64;
28	    for message in messages {
29	        let Some(message) = message.as_object() else { return fallback };
30	        match message.get("content") {
31	            None | Some(Value::Null) => {}
32	            Some(Value::String(text)) => text_bytes = text_bytes.saturating_add(text.len()),
33	            Some(Value::Array(parts)) => {
34	                for part in parts {
35	                    match (part.get("type").and_then(Value::as_str), part.get("text").and_then(Value::as_str)) {
36	                        (Some("text"), Some(text)) => text_bytes = text_bytes.saturating_add(text.len()),
37	                        (Some(_), _) => other_parts = other_parts.saturating_add(1),
38	                        (None, _) => return fallback,
39	                    }
40	                }
41	            }
42	            Some(_) => return fallback,
43	        }
44	    }
45	    bytes_to_tokens(text_bytes).saturating_add(other_parts.saturating_mul(NON_TEXT_PART_TOKENS))
46	}
47	
48	/// What a non-stream `2xx` body says about its tokens.
49	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
50	pub enum BodyUsage {
51	    /// `usage.total_tokens`.
52	    Reported(u64),
53	    /// D14: `ceil(len / 4)` of every `choices[].message.content` and tool-call `arguments`.
54	    Completion(u64),
55	}
56	
57	pub fn non_stream_usage(body: &[u8]) -> BodyUsage {
58	    let Ok(value) = serde_json::from_slice::<Value>(body) else {
59	        return BodyUsage::Completion(0);
60	    };
61	    if let Some(total) = value.pointer("/usage/total_tokens").and_then(Value::as_u64) {
62	        return BodyUsage::Reported(total);
63	    }
64	    let mut bytes = 0usize;
65	    for choice in value.get("choices").and_then(Value::as_array).into_iter().flatten() {
66	        if let Some(content) = choice.pointer("/message/content").and_then(Value::as_str) {
67	            bytes = bytes.saturating_add(content.len());
68	        }
69	        for call in choice.pointer("/message/tool_calls").and_then(Value::as_array).into_iter().flatten() {
70	            if let Some(arguments) = call.pointer("/function/arguments").and_then(Value::as_str) {
71	                bytes = bytes.saturating_add(arguments.len());
72	            }
73	        }
74	    }
75	    BodyUsage::Completion(bytes_to_tokens(bytes))
76	}
77	
78	/// Reads a copy of a forwarded SSE stream (§ 4.6). Every complete `data:` record that is not
79	/// `[DONE]` and holds no usage object adds one to the completion estimate (an OpenAI chunk
80	/// usually carries one token). A record that holds `"usage":{` is parsed, and the last
81	/// `usage.total_tokens` seen wins. A blank line completes a record. At the end of the stream,
82	/// `finish()` also completes the last record (SMA-730).
83	#[derive(Debug, Default)]
84	pub struct UsageScanner {
85	    /// The current partial line, bounded by `MAX_RECORD_BYTES`.
86	    line: Vec<u8>,
87	    /// Bytes of the current line, also when they were not buffered.
88	    line_len: usize,
89	    /// The last byte was CR: an LF right after it belongs to the same terminator.
90	    after_cr: bool,
91	    /// The current record's `data` value (lines joined with LF), bounded.
92	    data: Vec<u8>,
93	    has_data: bool,
94	    record_bytes: usize,
95	    oversized: bool,
96	    records: u64,
97	    reported: Option<u64>,
98	}
99	
100	impl UsageScanner {
101	    pub fn new() -> Self {
102	        Self::default()
103	    }
104	
105	    pub fn feed(&mut self, chunk: &[u8]) {
106	        for &byte in chunk {
107	            if self.after_cr {
108	                self.after_cr = false;
109	                if byte == b'\n' {
110	                    continue;
111	                }
112	            }
113	            match byte {
114	                b'\n' => self.end_line(),
115	                b'\r' => {
116	                    self.end_line();
117	                    self.after_cr = true;
118	                }
119	                _ => {
120	                    self.line_len = self.line_len.saturating_add(1);
121	                    self.record_bytes = self.record_bytes.saturating_add(1);
122	                    if self.record_bytes > MAX_RECORD_BYTES {
123	                        self.oversized = true;
124	                        self.line.clear();
125	                        self.data.clear();
126	                    } else {
127	                        self.line.push(byte);
128	                    }
129	                }
130	            }
131	        }
132	    }
133	
134	    /// The upstream stream ended, or failed. Close a pending line and a pending record, as a
135	    /// blank line does (SMA-730). A second call does nothing.
136	    pub fn finish(&mut self) {
137	        self.feed(b"\n\n");
138	    }
139	
140	    pub fn completion_records(&self) -> u64 {
141	        self.records
142	    }
143	
144	    pub fn reported_total(&self) -> Option<u64> {
145	        self.reported
146	    }
147	
148	    fn end_line(&mut self) {
149	        if self.line_len == 0 {
150	            self.end_record();
151	            return;
152	        }
153	        self.line_len = 0;
154	        let line = std::mem::take(&mut self.line);
155	        if self.oversized {
156	            return;
157	        }
158	        if let Some(value) = line.strip_prefix(b"data:") {
159	            let value = value.strip_prefix(b" ").unwrap_or(value);
160	            if self.has_data {
161	                self.data.push(b'\n');
162	            }
163	            self.data.extend_from_slice(value);
164	            self.has_data = true;
165	        }
166	    }
167	
168	    fn end_record(&mut self) {
169	        if self.oversized {
170	            self.records = self.records.saturating_add(1);
171	        } else if self.has_data {
172	            self.dispatch();
173	        }
174	        self.data.clear();
175	        self.has_data = false;
176	        self.oversized = false;
177	        self.record_bytes = 0;
178	    }
179	
180	    fn dispatch(&mut self) {
181	        if self.data.as_slice() == b"[DONE]" {
182	            return;
183	        }
184	        if has_usage_object(&self.data)
185	            && let Some(total) = serde_json::from_slice::<Value>(&self.data).ok().and_then(|v| v.pointer("/usage/total_tokens").and_then(Value::as_u64))
186	        {
187	            self.reported = Some(total);
188	            return;
189	        }
190	        self.records = self.records.saturating_add(1);
191	    }
192	}
193	
194	/// `"usage"` + optional whitespace + `:` + optional whitespace + `{`. With `include_usage`,
195	/// OpenAI sends `"usage":null` in every chunk, so a match on `"usage"` alone would parse every
196	/// record.
197	fn has_usage_object(data: &[u8]) -> bool {
198	    const KEY: &[u8] = b"\"usage\"";
199	    let mut rest = data;
200	    while let Some(pos) = rest.windows(KEY.len()).position(|w| w == KEY) {
201	        rest = &rest[pos + KEY.len()..];
202	        if let Some(after_colon) = trim_start(rest).strip_prefix(b":")
203	            && trim_start(after_colon).first() == Some(&b'{')
204	        {
205	            return true;
206	        }
207	    }
208	    false
209	}
210	
211	fn trim_start(bytes: &[u8]) -> &[u8] {
212	    let start = bytes.iter().position(|b| !b.is_ascii_whitespace()).unwrap_or(bytes.len());
213	    &bytes[start..]
214	}
