1	// SPDX-License-Identifier: Apache-2.0
2	
3	//! The inbound chat-completion request DTO.
4	//!
5	//! G7 parses the caller's JSON body into [`ChatCompletionRequest`] for exactly two reasons: to
6	//! read `model` (request logging) and `stream` (choosing the streaming vs non-streaming egress
7	//! path). It is **not** the wire body sent upstream — the OpenAI client forwards the caller's
8	//! ORIGINAL raw bytes verbatim (see [`crate::adapters::openai`]), so passthrough is byte-lossless
9	//! regardless of anything this DTO does or does not model.
10	//!
11	//! `#[serde(flatten)] extra` therefore exists as a belt-and-braces guarantee: every field this
12	//! struct does not name is preserved rather than dropped, so a re-serialization would still be
13	//! lossless (a secondary safety net, not the primary passthrough mechanism).
14	
15	use serde::{Deserialize, Serialize};
16	
17	/// An OpenAI-compatible `POST /v1/chat/completions` request body, modelled just enough for the
18	/// gateway's needs. `model` and `messages` are the required core; `stream` selects the egress
19	/// path (defaults to `false` when absent); every other top-level field (`temperature`, `top_p`,
20	/// `tools`, `response_format`, …) is captured losslessly in [`extra`](Self::extra).
21	#[derive(Debug, Clone, Deserialize, Serialize)]
22	pub struct ChatCompletionRequest {
23	    /// The target model id (read for request logging; the upstream body carries it verbatim).
24	    pub model: String,
25	    /// Whether the caller requested a streamed (SSE) completion. Absent → `false`.
26	    #[serde(default)]
27	    pub stream: bool,
28	    /// The conversation turns, kept as opaque JSON. The gateway reads only the lengths of the
29	    /// message text, to estimate tokens. It never logs the content and never changes it.
30	    pub messages: Vec<serde_json::Value>,
31	    /// Every unmodelled top-level field, preserved verbatim so a round-trip is lossless.
32	    #[serde(flatten)]
33	    pub extra: serde_json::Map<String, serde_json::Value>,
34	}
