41	    #[test]
42	    fn parses_core_fields_and_captures_unknowns_in_extra() {
43	        // A realistic request carrying `model`/`stream`/`messages` plus several unmodelled
44	        // top-level fields — the exact shape a caller's OpenAI SDK emits.
45	        let raw = json!({
46	            "model": "gpt-4o-mini",
47	            "stream": true,
48	            "messages": [{ "role": "user", "content": "hi" }],
49	            "temperature": 0.7,
50	            "top_p": 0.9,
51	            "tools": [{ "type": "function", "function": { "name": "f" } }],
52	            "response_format": { "type": "json_object" }
53	        });
54	
55	        let req: ChatCompletionRequest = serde_json::from_value(raw).expect("valid request parses");
56	
57	        assert_eq!(req.model, "gpt-4o-mini");
58	        assert!(req.stream);
59	        assert_eq!(req.messages.len(), 1);
60	
61	        // Every unknown top-level field landed in `extra` — and NOTHING that was named leaked
62	        // into it.
63	        assert_eq!(req.extra.get("temperature"), Some(&json!(0.7)));
64	        assert_eq!(req.extra.get("top_p"), Some(&json!(0.9)));
65	        assert_eq!(req.extra.get("tools"), Some(&json!([{ "type": "function", "function": { "name": "f" } }])));
66	        assert_eq!(req.extra.get("response_format"), Some(&json!({ "type": "json_object" })));
67	        assert!(!req.extra.contains_key("model"), "named fields must not bleed into `extra`");
68	        assert!(!req.extra.contains_key("stream"));
69	        assert!(!req.extra.contains_key("messages"));
70	    }
