76	            "messages": [{ "role": "system", "content": "be terse" }],
77	            "temperature": 0.2,
78	            "seed": 42,
79	            "metadata": { "team": "a", "nested": { "k": "v" } }
80	        });
81	
82	        let req: ChatCompletionRequest = serde_json::from_value(raw.clone()).expect("valid request parses");
83	        let reserialized = serde_json::to_value(&req).expect("re-serializes");
84	
85	        // The extra fields survive the round-trip byte-for-value (order-independent JSON equality).
86	        assert_eq!(reserialized.get("temperature"), Some(&json!(0.2)));
87	        assert_eq!(reserialized.get("seed"), Some(&json!(42)));
88	        assert_eq!(reserialized.get("metadata"), Some(&json!({ "team": "a", "nested": { "k": "v" } })));
89	        // Core fields survive too, at the top level (flatten does not nest them).
90	        assert_eq!(reserialized.get("model"), Some(&json!("gpt-4o")));
91	        assert_eq!(reserialized.get("messages"), raw.get("messages"));
92	    }
