385	    /// Allows everything after a short wait, and records the most decisions ever in flight.
386	    #[derive(Default)]
387	    struct SlowCounting {
388	        in_flight: Arc<AtomicUsize>,
389	        max_in_flight: Arc<AtomicUsize>,
390	        calls: Arc<AtomicUsize>,
391	    }
392	
393	    impl ToolCallDecider for SlowCounting {
394	        fn decide(&self, _ctx: Arc<DecisionContext>, _turn: Arc<ToolTurn>, calls: Vec<ToolCall>) -> DecideFuture {
395	            let (in_flight, max, count) = (Arc::clone(&self.in_flight), Arc::clone(&self.max_in_flight), Arc::clone(&self.calls));
396	            Box::pin(async move {
397	                let now = in_flight.fetch_add(1, Ordering::SeqCst) + 1;
398	                max.fetch_max(now, Ordering::SeqCst);
399	                count.fetch_add(1, Ordering::SeqCst);
400	                tokio::time::sleep(Duration::from_millis(30)).await;
401	                in_flight.fetch_sub(1, Ordering::SeqCst);
402	                Ok(vec![Decision::Allow; calls.len()])
403	            })
404	        }
405	    }
406	
407	    /// Never answers for a call named `hang_*`; allows everything else at once.
408	    struct HangNamed;
409	
410	    impl ToolCallDecider for HangNamed {
411	        fn decide(&self, _ctx: Arc<DecisionContext>, _turn: Arc<ToolTurn>, calls: Vec<ToolCall>) -> DecideFuture {
412	            if calls.iter().any(|c| c.name.starts_with("hang_")) {
413	                return Box::pin(std::future::pending());
