73	/// Proxy a chat-completion request to the OpenAI upstream.
74	///
75	/// Extractor order matters: [`State`] and [`Extension`] are `FromRequestParts` (they read only the
76	/// head), while [`EnvelopeBytes`] is `FromRequest` (it consumes the body) and so must come LAST.
77	/// [`EnvelopeBytes`] wraps [`Bytes`], so it honours the
78	/// [`DefaultBodyLimit`](axum::extract::DefaultBodyLimit) layer the same way and returns `413`
79	/// for an over-limit body before this function body runs — rendered through the OpenAI envelope
80	/// rather than as axum's plain text (SMA-588). It is still `FromRequest`, so it must come LAST.
81	///
82	/// `CallerContext` is taken as `Option<Extension<_>>` for defence in depth: the G5 middleware
83	/// guarantees its presence on any request routed here, so its absence is an unreachable internal
84	/// bug surfaced as a `500` (rendered through the OpenAI envelope) rather than axum's default
85	/// extension-missing response.
86	pub(crate) async fn chat_completions(State(state): State<AppState>, caller: Option<Extension<CallerContext>>, EnvelopeBytes(body): EnvelopeBytes) -> Response {
87	    let Some(Extension(caller)) = caller else {
88	        // Unreachable in practice — the auth middleware always attaches a CallerContext.
89	        return GatewayError::Internal.into_response();
90	    };
91	
92	    // Parse a COPY only to read `model` + `stream`; the ORIGINAL `body` bytes flow upstream
93	    // verbatim. SMA-588 splits the failure: `serde_json` classifies its own errors, so a body
94	    // that PARSED but did not match the type is reported distinctly from one that could not be
95	    // read at all. `Category::Io` cannot arise from a `&[u8]`, but is grouped with the
96	    // unreadable cases so the match is exhaustive without a wildcard.
97	    let dto: ChatCompletionRequest = match serde_json::from_slice(&body) {
98	        Ok(dto) => dto,
99	        Err(e) => {
100	            return match e.classify() {
101	                serde_json::error::Category::Data => GatewayError::InvalidRequestSchema.into_response(),
102	                serde_json::error::Category::Syntax | serde_json::error::Category::Eof | serde_json::error::Category::Io => GatewayError::BadRequestBody.into_response(),
103	            };
104	        }
105	    };
106	    let model = dto.model;
107	    let stream = dto.stream;
108	    let messages = dto.messages;
109	
110	    // SMA-505 D9: streaming is a request PARAMETER, not a route, so a disabled capability is
111	    // enforced here rather than by unmounting. Checked before any egress call, so a refused
112	    // request never reaches the upstream or its rate limit.
113	    if stream && !state.capabilities.chat_stream {
114	        return GatewayError::StreamingDisabled.into_response();
115	    }
116	
117	    // SMA-677 D9: the limits run after the body and streaming checks and just before egress, so a
118	    // refused body never uses quota. `None` (no `[limits]` table) skips them entirely (A6).
119	    let mut guard = match &state.limits {
120	        None => None,
121	        Some(limits) => match limits.admit(&caller).await {
122	            Ok(guard) => Some(guard),
123	            Err(refusal) => {
124	                // The refusal metric is the operator's signal; this line stays at debug.
125	                tracing::debug!(principal = %caller.principal_prn, scope = %caller.scope_prn, reason = refusal.label(), "chat completion refused by a limit");
126	                return GatewayError::from(refusal).into_response();
127	            }
128	        },
129	    };
130	    if let Some(guard) = guard.as_mut() {
131	        guard.set_request_estimate(usage::request_tokens_estimate(&messages, body.len()));
132	        // The ids exist here; inside the stream `current_ids()` is `None` (SMA-504 § 4.3).
133	        guard.set_ids(paigasus_observability::current_ids());
134	        guard.mark_sent();
135	    }
136	
137	    // SMA-749: capture what the decider needs while the request ids still exist (SMA-504 § 4.3:
138	    // inside the stream they are `None`). Parsed from the same raw bytes that go upstream.
139	    // `None` when interception is off: nothing is parsed or constructed (D27).
140	    let interception = state.tool_interception.clone().map(|ti| {
141	        let turn = Arc::new(paigasus_gateway_core::parse_request(paigasus_gateway_core::Format::OpenAiChat, &body));
142	        let request_id = paigasus_observability::current_ids().map(|ids| ids.request_id.to_string());
143	        let ctx = Arc::new(paigasus_gateway_core::DecisionContext::new(caller.principal_prn.clone(), caller.scope_prn.clone(), request_id));
144	        (ti, ctx, turn)
145	    });
146	
147	    let started = Instant::now();
148	    // EGRESS HYGIENE: only the raw body bytes cross the boundary — never the caller's headers.
149	    let result = state.openai.chat_completion(body, stream).await;
150	
151	    let (response, status) = match result {
152	        Ok(ChatResponse::Full { status, body }) => {
153	            // Non-stream: the upstream head AND body have both landed, so this is a genuine
154	            // full-request latency, not just TTFB (see the NOTE on the stream arm below).
155	            record_upstream_call(status, started);
156	            // A4: a 2xx reads a COPY of the body for its usage; a non-2xx charges nothing.
157	            if let Some(guard) = guard.as_mut() {
158	                if status.is_success() {
159	                    match usage::non_stream_usage(&body) {
160	                        BodyUsage::Reported(total) => guard.set_reported(total),
161	                        BodyUsage::Completion(tokens) => guard.set_completion_estimate(tokens),
162	                    }
163	                } else {
164	                    guard.mark_no_charge();
165	                }
166	            }
167	            // SMA-749 § 5.2: the guard read the ORIGINAL body above (D24); interception runs after.
168	            let outcome = match &interception {
169	                Some((ti, ctx, turn)) if status.is_success() => super::interception::intercept_body(ti, Arc::clone(ctx), Arc::clone(turn), &body).await,
170	                _ => super::interception::BodyOutcome::Forward { rewritten: None, report: None },
171	            };
172	            match outcome {
173	                super::interception::BodyOutcome::Refuse => {
174	                    let resp = GatewayError::ToolInterceptionMalformedResponse.into_response();
175	                    let status = resp.status();
176	                    (resp, status)
177	                }
178	                super::interception::BodyOutcome::Forward { rewritten, report } => {
179	                    let body = rewritten.unwrap_or(body);
180	                    // Forward the upstream status + body VERBATIM (or rewritten by a block),
181	                    // including a non-2xx OpenAI error envelope.
182	                    let mut resp = (status, [(header::CONTENT_TYPE, "application/json")], body).into_response();
183	                    if let Some(r) = report
184	                        && let Ok(v) = axum::http::HeaderValue::from_str(&r)
185	                    {
186	                        resp.headers_mut().insert("paigasus-tool-decisions", v);
187	                    }
188	                    (resp, status)
189	                }
190	            }
191	        }
192	        Ok(ChatResponse::Stream { status, stream }) => {
193	            // NOTE: for `stream:true` this records TTFB (time-to-first-byte / response head), NOT
194	            // stream completion — the call is considered "done" for metrics purposes the moment
195	            // the upstream response head arrives. A mid-stream SSE failure (handled below by the
196	            // terminal-error adapter, once the 200 head is already committed) is NOT re-counted
197	            // here — it has no separate HTTP status to attribute.
198	            record_upstream_call(status, started);
199	            let resp = if status.is_success() {
200	                // Success stream: SSE passthrough with the mid-stream terminal-error adapter.
201	                //
202	                // SMA-504 spec §4.3, situation 3: `current_ids() == None` from here on. The
203	                // `CorrelationLayer`'s task-local scope covers the request-HEAD future only, and
204	                // that future already resolved to this `Response<Body>` the moment this line
205	                // runs — hyper polls the `Body::from_stream` future (and therefore
206	                // `terminal_sse_error_stream` below) AFTERWARDS, outside the scope. Anything
207	                // added inside the stream adapter — a log line, a metric — will see no ids.
208	                let body = match interception {
209	                    // SMA-749: the interceptor owns the terminal frame from here on (D17).
210	                    Some((ti, ctx, turn)) => Body::from_stream(super::interception::intercepted_stream(stream, guard.take(), ti, ctx, turn, TERMINAL_SSE_ERROR.as_bytes())),
211	                    None => Body::from_stream(terminal_sse_error_stream(stream, guard.take())),
212	                };
213	                (status, [(header::CONTENT_TYPE, "text/event-stream")], body).into_response()
214	            } else {
215	                // Non-2xx `stream:true` request: OpenAI answers with a JSON error body (NOT SSE), so
216	                // forward it as an error passthrough — no SSE terminal-error wrapping applies.
217	                if let Some(guard) = guard.as_mut() {
218	                    guard.mark_no_charge();
219	                }
220	                (status, [(header::CONTENT_TYPE, "application/json")], Body::from_stream(stream)).into_response()
221	            };
222	            (resp, status)
223	        }
224	        Err(err) => {
225	            // Connect/transport/build → 502; timeout → 504 (see `GatewayError::from`). No upstream
226	            // HTTP status exists in this case at all, so record under the MAPPED gateway status
227	            // instead (still a `status_class` derived from an HTTP status, per the global
228	            // constraints — never a free-form error string).
229	            // A4: a connect failure never reached the upstream; any other failure after the send
230	            // (timeout, transport) keeps the request estimate.
231	            if matches!(err, OpenAiError::Connect(_))
232	                && let Some(guard) = guard.as_mut()
233	            {
234	                guard.mark_no_charge();
235	            }
236	            let resp = GatewayError::from(err).into_response();
237	            let status = resp.status();
238	            record_upstream_call(status, started);
239	            (resp, status)
240	        }
241	    };
242	
243	    // One structured line per request — model/stream/status/latency/principal/scope/credential
244	    // ONLY. NEVER the prompt, messages, body, or the OpenAI key. `principal` is a service account
245	    // for an API key and a USER for an OIDC token (SMA-635): a principal PRN is an opaque id, not
246	    // the user's name or e-mail, and it is kept deliberately for attribution and audit. The "never
247	    // PII" bar is about prompt/message content. `key_id` is logged only for an API key.
248	    match &caller.credential {
249	        Credential::ApiKey { key_id } => tracing::info!(
250	            model = %model,
251	            stream = stream,
252	            status = status.as_u16(),
253	            latency_ms = started.elapsed().as_millis() as u64,
254	            principal = %caller.principal_prn,
255	            scope = %caller.scope_prn,
256	            auth = "api_key",
257	            key_id = %key_id,
258	            "chat completion proxied"
259	        ),
260	        Credential::Oidc => tracing::info!(
261	            model = %model,
262	            stream = stream,
263	            status = status.as_u16(),
264	            latency_ms = started.elapsed().as_millis() as u64,
265	            principal = %caller.principal_prn,
266	            scope = %caller.scope_prn,
267	            auth = "oidc",
268	            "chat completion proxied"
269	        ),
270	    }
271	
272	    response
273	}
