275	/// Record `gateway_upstream_requests_total{status_class}` + `gateway_upstream_request_duration_seconds`
276	/// for one call to [`OpenAiClient::chat_completion`]. `status` is either the upstream's OWN status
277	/// (a completed response, full or streamed) or, on a transport/connect/timeout failure, the
278	/// GATEWAY status the error was mapped to (502/504 — see `GatewayError::from<OpenAiError>`), since
279	/// no upstream status exists in that case. See the call sites above for the TTFB-vs-stream-vs-full
280	/// timing note.
281	fn record_upstream_call(status: StatusCode, started: Instant) {
282	    let status_class = format!("{}xx", status.as_u16() / 100);
283	    counter!(names::GATEWAY_UPSTREAM_REQUESTS_TOTAL, "status_class" => status_class).increment(1);
284	    histogram!(names::GATEWAY_UPSTREAM_REQUEST_DURATION_SECONDS).record(started.elapsed().as_secs_f64());
285	}
