287	/// The small state machine [`terminal_sse_error_stream`] unfolds over: still forwarding upstream
288	/// chunks, or terminated (after emitting the terminal error event, or after the upstream ended).
289	enum StreamState {
290	    Streaming(OpenAiByteStream),
291	    Done,
292	}
293	
294	/// The unfold state. The charge guard is a FIELD here, not a `Drop` on `StreamState`: the closure
295	/// destructures the state by move, which a type with `Drop` forbids (E0509). When the stream ends,
296	/// fails, or is dropped, this value drops once, and the guard with it (SMA-677 § 4.6). The clean
297	/// end and the first error call `UsageScanner::finish()` first; a drop (client disconnect) does
298	/// not, so a last record with no blank line counts only when the upstream ended (SMA-730 D3).
299	struct Relay {
300	    phase: StreamState,
301	    scan: UsageScanner,
302	    guard: Option<ChargeGuard>,
303	}
304	
305	/// One upstream chunk, read for billing before anything else sees it (SMA-677, SMA-749 D24).
306	/// Without a guard (no `[limits]`) nothing is parsed at all. Shared with the intercepting relay.
307	pub(crate) fn feed_scan(scan: &mut UsageScanner, guard: &mut Option<ChargeGuard>, chunk: &[u8]) {
308	    if let Some(guard) = guard.as_mut() {
309	        scan.feed(chunk);
310	        guard.set_stream_progress(scan.completion_records(), scan.reported_total());
311	    }
312	}
313	
314	/// SMA-730: the upstream ended or failed. A last record with no blank line after it still
315	/// counts. Without a guard the scanner reads nothing, as in the chunk arm. Shared with the
316	/// intercepting relay (SMA-749 D24).
317	pub(crate) fn finish_scan(scan: &mut UsageScanner, guard: &mut Option<ChargeGuard>) {
318	    if let Some(guard) = guard.as_mut() {
319	        scan.finish();
320	        guard.set_stream_progress(scan.completion_records(), scan.reported_total());
321	    }
322	}
323	
324	/// Adapt an [`OpenAiByteStream`] into a body stream that forwards each upstream chunk UNBUFFERED
325	/// and, on the FIRST upstream error, emits one terminal [`TERMINAL_SSE_ERROR`] event and ends.
326	///
327	/// Items are `Result<Bytes, Infallible>`: the outgoing stream never errors (a mid-stream upstream
328	/// failure becomes a data event, not a transport error), which keeps `Body::from_stream` from
329	/// aborting the response body. The inner stream is owned by the unfold state and dropped when this
330	/// stream is dropped — preserving reqwest's cancel-on-drop of the upstream request.
331	///
332	/// Runs with `paigasus_observability::current_ids() == None` (SMA-504 spec §4.3, situation 3):
333	/// this function is polled by hyper after the request-head future — the one the
334	/// `CorrelationLayer` task-local scope covers — has already resolved. See the call site's
335	/// comment in `chat_completions`.
336	fn terminal_sse_error_stream(inner: OpenAiByteStream, guard: Option<ChargeGuard>) -> impl Stream<Item = Result<Bytes, Infallible>> + Send + 'static {
337	    let start = Relay {
338	        phase: StreamState::Streaming(inner),
339	        scan: UsageScanner::new(),
340	        guard,
341	    };
342	    futures::stream::unfold(start, |Relay { phase, mut scan, mut guard }| async move {
343	        match phase {
344	            StreamState::Streaming(mut inner) => match inner.next().await {
345	                // Forward each chunk exactly as it arrived (unbuffered). The scanner reads a copy,
346	                // and only when a guard exists (no `[limits]`: no parsing at all).
347	                Some(Ok(chunk)) => {
348	                    feed_scan(&mut scan, &mut guard, &chunk);
349	                    Some((
350	                        Ok(chunk),
351	                        Relay {
352	                            phase: StreamState::Streaming(inner),
353	                            scan,
354	                            guard,
355	                        },
356	                    ))
357	                }
358	                // First upstream error: count the last record (the frame's leading blank line
359	                // closes it for the client too), emit the terminal event, then end.

