1	// SPDX-License-Identifier: Apache-2.0
2	//! The request side of a turn (spec D19): what tools the caller declared, what it called before,
3	//! and which results it sent back. Never the content of a tool result. No request rewrite.
4	
5	use serde_json::{Map, Value};
6	
7	use crate::json::{Malformed, opt_obj, opt_str, parse_strict};
8	use crate::types::{Format, ToolCallKind};
9	
10	#[non_exhaustive]
11	#[derive(Debug, Clone, PartialEq)]
12	pub enum ToolTurn {
13	    Parsed(TurnFacts),
14	    /// The request could not be read. Sequence rules (SMA-753) must treat this as unknown history,
15	    /// never as an empty one.
16	    Unavailable(&'static str),
17	}
18	
19	#[non_exhaustive]
20	#[derive(Debug, Clone, Default, PartialEq)]
21	pub struct TurnFacts {
22	    pub definitions: Vec<ToolDefinition>,
23	    pub prior_calls: Vec<PriorCall>,
24	    pub tool_results: Vec<ToolResultRef>,
25	}
26	
27	/// A tool the caller declared. `Debug` prints `schema`; never log a definition with `{:?}`.
28	#[non_exhaustive]
29	#[derive(Debug, Clone, PartialEq)]
30	pub struct ToolDefinition {
31	    pub name: String,
32	    pub kind: ToolCallKind,
33	    pub schema: Option<Value>,
34	}
35	
36	/// A call the caller made on an earlier turn. `Debug` prints `arguments`, which may carry
37	/// secrets; never log a prior call with `{:?}`.
38	#[non_exhaustive]
39	#[derive(Debug, Clone, PartialEq, Eq)]
40	pub struct PriorCall {
41	    pub id: Option<String>,
42	    pub name: String,
43	    pub arguments: String,
44	}
45	
46	/// A reference to a tool result. It never holds the result content.
47	#[non_exhaustive]
48	#[derive(Debug, Clone, PartialEq, Eq)]
49	pub struct ToolResultRef {
50	    pub call_id: Option<String>,
51	    pub name: Option<String>,
52	}
53	
54	#[must_use]
55	pub fn parse_request(format: Format, body: &[u8]) -> ToolTurn {
56	    let parsed = parse_strict(body).and_then(|v| match format {
57	        Format::OpenAiChat => openai(&v),
58	        Format::AnthropicMessages => anthropic(&v),
59	    });
60	    match parsed {
61	        Ok(f) => ToolTurn::Parsed(f),
62	        Err(_) => ToolTurn::Unavailable("malformed"),
63	    }
64	}
65	
66	fn arr<'a>(o: &'a Map<String, Value>, k: &'static str) -> Result<&'a [Value], Malformed> {
67	    match o.get(k) {
68	        None | Some(Value::Null) => Ok(&[]),
69	        Some(Value::Array(a)) => Ok(a),
70	        Some(_) => Err(Malformed(k)),
71	    }
72	}
73	
74	fn obj(v: &Value) -> Result<&Map<String, Value>, Malformed> {
75	    v.as_object().ok_or(Malformed("object"))
76	}
77	
78	fn req_str(o: &Map<String, Value>, k: &'static str) -> Result<String, Malformed> {
79	    opt_str(o.get(k), k)?.ok_or(Malformed(k))
80	}
81	
82	fn openai(v: &Value) -> Result<TurnFacts, Malformed> {
83	    let top = obj(v)?;
84	    let mut f = TurnFacts::default();
85	    for t in arr(top, "tools")? {
86	        let t = obj(t)?;
87	        match opt_str(t.get("type"), "type")?.as_deref() {
88	            Some("function") => {
89	                let func = opt_obj(t.get("function"), "function")?.ok_or(Malformed("function"))?;
90	                f.definitions.push(ToolDefinition {
91	                    name: req_str(func, "name")?,
92	                    kind: ToolCallKind::Function,
93	                    schema: func.get("parameters").cloned(),
94	                });
95	            }
96	            Some("custom") => {
97	                let c = opt_obj(t.get("custom"), "custom")?.ok_or(Malformed("custom"))?;
98	                f.definitions.push(ToolDefinition {
99	                    name: req_str(c, "name")?,
100	                    kind: ToolCallKind::Custom,
101	                    schema: None,
102	                });
103	            }
104	            _ => {}
105	        }
106	    }
107	    for d in arr(top, "functions")? {
108	        let d = obj(d)?;
109	        f.definitions.push(ToolDefinition {
110	            name: req_str(d, "name")?,
111	            kind: ToolCallKind::LegacyFunctionCall,
112	            schema: d.get("parameters").cloned(),
113	        });
114	    }
115	    for m in arr(top, "messages")? {
116	        let m = obj(m)?;
117	        match opt_str(m.get("role"), "role")?.as_deref() {
118	            Some("assistant") => {
119	                for c in arr(m, "tool_calls")? {
120	                    let c = obj(c)?;
121	                    let (name, arguments) = prior_body(c)?;
122	                    f.prior_calls.push(PriorCall {
123	                        id: opt_str(c.get("id"), "id")?,
124	                        name,
125	                        arguments,
126	                    });
127	                }
128	                if let Some(fc) = opt_obj(m.get("function_call"), "function_call")? {
129	                    f.prior_calls.push(PriorCall {
130	                        id: None,
131	                        name: req_str(fc, "name")?,
132	                        arguments: opt_str(fc.get("arguments"), "arguments")?.unwrap_or_default(),
133	                    });
134	                }
135	            }
136	            Some("tool") => f.tool_results.push(ToolResultRef {
137	                call_id: opt_str(m.get("tool_call_id"), "tool_call_id")?,
138	                name: None,
139	            }),
140	            Some("function") => f.tool_results.push(ToolResultRef {
141	                call_id: None,
142	                name: opt_str(m.get("name"), "name")?,
143	            }),
144	            _ => {}
145	        }
146	    }
147	    Ok(f)
148	}
149	
150	/// The (name, arguments) of a prior OpenAI tool call: a `function` body's name and arguments, or a
151	/// `custom` body's name and input. An entry with neither body, both, or a body that disagrees with
152	/// its `type` is malformed: an empty name would read as a call to no tool at all.
153	fn prior_body(c: &Map<String, Value>) -> Result<(String, String), Malformed> {
154	    let ty = opt_str(c.get("type"), "type")?;
155	    let (body, input) = match (opt_obj(c.get("function"), "function")?, opt_obj(c.get("custom"), "custom")?, ty.as_deref()) {
156	        (Some(x), None, None | Some("function")) => (x, "arguments"),
157	        (None, Some(x), None | Some("custom")) => (x, "input"),
158	        _ => return Err(Malformed("tool_call")),
159	    };
160	    Ok((req_str(body, "name")?, opt_str(body.get(input), input)?.unwrap_or_default()))
161	}
162	
163	fn anthropic(v: &Value) -> Result<TurnFacts, Malformed> {
164	    let top = obj(v)?;
165	    let mut f = TurnFacts::default();
166	    for t in arr(top, "tools")? {
167	        let t = obj(t)?;
168	        match opt_str(t.get("type"), "type")?.as_deref() {
169	            None | Some("custom") => f.definitions.push(ToolDefinition {
170	                name: req_str(t, "name")?,
171	                kind: ToolCallKind::AnthropicToolUse,
172	                schema: t.get("input_schema").cloned(),
173	            }),
174	            Some(_) => {} // a server tool
175	        }
176	    }
177	    for m in arr(top, "messages")? {
178	        let m = obj(m)?;
179	        let Some(Value::Array(blocks)) = m.get("content") else { continue };
180	        for b in blocks {
181	            let b = obj(b)?;
182	            match opt_str(b.get("type"), "type")?.as_deref() {
183	                Some("tool_use") => f.prior_calls.push(PriorCall {
184	                    id: opt_str(b.get("id"), "id")?,
185	                    name: req_str(b, "name")?,
186	                    arguments: b.get("input").map(Value::to_string).unwrap_or_default(),
187	                }),
188	                Some("tool_result") => f.tool_results.push(ToolResultRef {
189	                    call_id: opt_str(b.get("tool_use_id"), "tool_use_id")?,
190	                    name: None,
191	                }),
192	                _ => {}
193	            }
194	        }
195	    }
196	    Ok(f)
197	}
