99	/// A decided call in the models' terms. A `tool_use` call's arguments are compared as parsed JSON,
100	/// because anthropic-python hands the client the parsed `input`, not the string.
101	pub fn as_model_call(c: &ToolCall) -> ModelCall {
102	    ModelCall {
103	        choice: c.choice,
104	        kind: kind_of(c.kind),
105	        name: c.name.clone(),
106	        arguments: c.arguments.clone(),
107	        parsed: false,
108	    }
109	}
110	
111	/// Whether a model call's arguments match a decided call's. The decider sees `{}` for empty
112	/// function arguments (the core's rule), so a client's raw `""` matches it. A `parsed` model value
113	/// is compared with the parsed decided string. The match is exact, also for the snapshot at an
114	/// excused raise: a prefix of allowed arguments can be a call that an argument-reading policy
115	/// (SMA-752) denies, and the gateway never asks the decider about it. The exception is kind
116	/// `other`: its arguments are not compared, because the decided form is the raw entry (spec § 4,
117	/// § 9).
