15	/// The tool calls of one complete body, and the means to rewrite it.
16	pub struct BodyCalls {
17	    format: Format,
18	    value: Value,
19	    pub calls: Vec<ToolCall>,
20	    pub unenforceable: Vec<ReportEntry>,
21	}
22	
23	/// Parse a complete `chat.completion` or Messages body (strictly) and extract its tool calls.
24	///
25	/// # Errors
26	/// `Malformed` when the body is over `max_bytes`, is not strict JSON, or is not in canonical form.
27	pub fn parse_body(format: Format, body: &[u8], max_bytes: usize) -> Result<BodyCalls, Malformed> {
28	    if body.len() > max_bytes {
29	        return Err(Malformed("too_large"));
30	    }
31	    let value = parse_strict(body)?;
32	    // serde_json has no arbitrary_precision: an integer beyond u64/i64 becomes an f64 and is
33	    // rounded, so the decider would see a different number than a client that keeps the exact int
34	    // (I1). Rejecting every such number up front also makes the single re-serialization in
35	    // `apply` exact for every number that remains, so the rewritten body cannot alter a value.
36	    check_numbers(&value)?;
37	    let (calls, unenforceable) = match format {
38	        Format::OpenAiChat => (openai::body::calls(&value)?, Vec::new()),
39	        Format::AnthropicMessages => anthropic::body::calls(&value)?,
40	    };
41	    Ok(BodyCalls { format, value, calls, unenforceable })
42	}
