44	impl BodyCalls {
45	    /// The block code of call `i`. A decision vector of the wrong length blocks every call (D18).
46	    fn code(&self, decisions: &[Decision], i: usize) -> Option<BlockCode> {
47	        if decisions.len() != self.calls.len() {
48	            return Some(BlockCode::DeciderError);
49	        }
50	        match decisions[i] {
51	            Decision::Block { code } => Some(code),
52	            _ => None,
53	        }
54	    }
55	
56	    /// The rewritten body, or `None` when nothing is blocked and the original bytes go through.
57	    #[must_use]
58	    pub fn apply(self, decisions: &[Decision]) -> Option<Vec<u8>> {
59	        let codes: Vec<Option<BlockCode>> = (0..self.calls.len()).map(|i| self.code(decisions, i)).collect();
60	        if codes.iter().all(Option::is_none) {
61	            return None;
62	        }
63	        let mut value = self.value;
64	        match self.format {
65	            Format::OpenAiChat => openai::body::rewrite(&mut value, &self.calls, &codes),
66	            Format::AnthropicMessages => anthropic::body::rewrite(&mut value, &self.calls, &codes),
67	        }
68	        Some(serde_json::to_vec(&value).expect("a Value always serializes"))
69	    }
70	
71	    /// The `paigasus-tool-decisions` header value (D22), including the unenforceable entries.
72	    #[must_use]
73	    pub fn report(&self, decisions: &[Decision], basis: Basis) -> String {
74	        let mut entries: Vec<ReportEntry> = self
75	            .calls
76	            .iter()
77	            .enumerate()
78	            .map(|(i, c)| {
79	                let code = self.code(decisions, i);
80	                let decision = if code.is_some() { ReportDecision::Block } else { ReportDecision::Allow };
81	                ReportEntry {
82	                    choice: c.choice,
83	                    position: c.position,
84	                    name: c.name.clone(),
85	                    decision,
86	                    basis: Some(basis),
87	                    code,
88	                }
89	            })
90	            .collect();
91	        entries.extend(self.unenforceable.iter().cloned());
92	        header_value(&entries)
93	    }
94	}
